    ('8baf0d5a-4f61-4d77-a3f9-2eba4321fadf'::uuid, 'card_description', 'A rugged hill blocking the "Jaws of Borrowdale" gorge. The summit held an ancient hillfort, though quarrying has sliced away the western face.', 'Wooded Castle Crag rises between Broadslack Gill and the Derwent. Its summit is believed to have been an ancient hill fort, its western section sliced away by quarrying.', 'teaser-card-s014:8baf0d5a-4f61-4d77-a3f9-2eba4321fadf:card_description', 'teaser-card-s014 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '321d96b5291b7d8ca1dedf973573e4bf97fbc27b600f9e2878126991f5942fd5|faccbfb1962fb86c125a6e093c4b0babf139fcd4646f889f81fd1d9e5378044e|faccbfb1962fb86c125a6e093c4b0babf139fcd4646f889f81fd1d9e5378044e', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Wooded Castle Crag rises between Broadslack Gill and the Derwent. Its summit is believed to have been an ancient hill fort, its western section sliced away by quarrying."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castle Crag is wooded [S2]; it rises between Broadslack Gill and the Derwent [S2]; its summit is believed to have been an ancient hill fort [S5]; its western section has been sliced away by quarrying [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castle Crag is a hill (fell) in the English Lake District (Borrowdale), with a summit area that is believed to have been an ancient hill fort - the site is a hill and hill fort in England [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Crag]; Castle Crag is wooded and rises between Broadslack Gill and the Derwent [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Crag]; The summit area is believed to have been an ancient hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Crag]; The western section of the summit has been sliced away by quarrying [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Crag]"}]'::jsonb),
    ('8c66d030-330a-4f76-9e07-8e1ed0b0f706'::uuid, 'card_description', 'A series of earthworks forming a dyke once running from Sheffield to Mexborough. Its purpose and date of construction remain genuinely unknown.', 'Its purpose and date unknown, the Roman Rig runs as earthworks through the north of Rotherham: perhaps a Brigantian defence against Rome, perhaps a guard of Elmet against the Angles.', 'teaser-card-s014:8c66d030-330a-4f76-9e07-8e1ed0b0f706:card_description', 'teaser-card-s014 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'ad3574b8435fd1b5c48925dca841531399e632b5503618a37f13efade1ade958|bdafbda2210ee374a4af9da781f973739c2c869910da51383d30d3ee1bd467b9|bdafbda2210ee374a4af9da781f973739c2c869910da51383d30d3ee1bd467b9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Its purpose and date unknown, the Roman Rig runs as earthworks through the north of Rotherham: perhaps a Brigantian defence against Rome, perhaps a guard of Elmet against the Angles."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the purpose and date of construction of the Roman Rig are unknown [S3]; the Roman Rig is a series of earthworks in the north of Rotherham [S1]; perhaps it was a defence by the Brigantian tribes against the Roman invasion [S4]; perhaps it was built to guard the kingdom of Elmet against the Angles [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Rig is a series of earthworks (a dyke) in the north of Rotherham, South Yorkshire, England - the site the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Rig]; Its purpose and date are unknown [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Rig]; It was perhaps built by the Brigantian tribes in the 1st century AD as a defence against the Roman invasion [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Rig]; It was perhaps built after the 5th century to defend the kingdom of Elmet from the Angles [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Rig]"}]'::jsonb),
    ('8d0a101a-45fb-42a3-8106-6a609161e7f1'::uuid, 'card_description', 'Built in 280 AD from local flint, chalk, and limestone, this farmhouse still stands near its original wall height. Its roof was massive limestone slabs, each pierced by a single nail hole.', 'Garage foundations laid in 1926 unearthed Newport Roman Villa, a farmhouse built about 280 AD, its walls almost at their original height and its bath suite warmed by a hypocaust.', 'teaser-card-s014:8d0a101a-45fb-42a3-8106-6a609161e7f1:card_description', 'teaser-card-s014 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '5f9cec6f04ee1a0c40a32e7eda8eed796532143d9bb1cd440cdd422861302024|fba7af32386168fc15dad98c6265c63420820b8611915188f887cd5aac6ad2a3|fba7af32386168fc15dad98c6265c63420820b8611915188f887cd5aac6ad2a3', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Garage foundations laid in 1926 unearthed Newport Roman Villa, a farmhouse built about 280 AD, its walls almost at their original height and its bath suite warmed by a hypocaust."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the villa was unearthed in 1926 [S3]; garage foundations being laid uncovered it [S3]; it is a farmhouse [S1]; it was built about 280 AD [S1, S5]; its walls remain almost at their original height [S5]; its bath suite is heated by a hypocaust [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Newport Roman Villa is a Roman (Romano-British) villa near Newport, Isle of Wight, England - the site the text is about [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; The villa was a farmhouse [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; The villa was unearthed when garage foundations were laid [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; The garage foundations were laid, and the villa unearthed, in 1926 [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; The farmhouse was built about 280 AD [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; Its walls remain almost at their original height [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; The villa has a Roman bath suite [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]; The bath suite was warmed by a hypocaust (underfloor heating) [SUPPORTED: https://en.wikipedia.org/wiki/Newport_Roman_Villa]"}]'::jsonb),
    ('8d0fb4aa-7eda-4d61-a313-5f270a2f5b8c'::uuid, 'card_description', 'A sunken Lycian city visible beneath clear Mediterranean waters, with submerged harbour, bathhouse, and fish sauce workshops. Earthquake and sea-level rise drowned it.', 'On the northern side of Kekova lie the partly sunken ruins of Batik Sehir Kekova, a town destroyed by an earthquake in the 2nd century, rebuilt, then abandoned because of Arab incursions.', 'teaser-card-s014:8d0fb4aa-7eda-4d61-a313-5f270a2f5b8c:card_description', 'teaser-card-s014 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'de25f6a63353e8f2cdd70379e7f57cd2983b69d1145daa13dec4b26294976f81|fd0438718470bf6c4a80049e53a46d38f6aecfebfa0c1ab652fdd2518f01b17d|fd0438718470bf6c4a80049e53a46d38f6aecfebfa0c1ab652fdd2518f01b17d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the northern side of Kekova lie the partly sunken ruins of Batik Sehir Kekova, a town destroyed by an earthquake in the 2nd century, rebuilt, then abandoned because of Arab incursions."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the ruins lie on the northern side of Kekova [S2]; the ruins are partly sunken [S2]; they are the ruins of a town [S2]; the town was destroyed by an earthquake in the 2nd century [S2]; the town was rebuilt [S3]; it was then abandoned because of Arab incursions [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The site is the partly sunken ruins of an ancient town on the island of Kekova, Turkey (the town of Dolichiste, known to visitors as the sunken city, Batik Sehir) [SUPPORTED: https://en.wikipedia.org/wiki/Kekova]; Batik Sehir (Batik Sehir Kekova, ''the Kekova Sunken City'') is the name of the sunken ruins of ancient Dolichiste on Kekova Island [SUPPORTED, no proving quote: https://theothertour.com/kekova/]; The ruins lie on the northern side of Kekova [SUPPORTED: https://en.wikipedia.org/wiki/Kekova]; The town was destroyed by an earthquake in the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Kekova]; The town was rebuilt (in the Byzantine period) [SUPPORTED: https://en.wikipedia.org/wiki/Kekova]; It was then abandoned because of Arab incursions [SUPPORTED: https://en.wikipedia.org/wiki/Kekova]"}]'::jsonb),
    ('8d416cb3-e799-4990-96a9-50a70fde39c2'::uuid, 'card_description', 'An Iron Age summit fort on a rocky peak with a stone rampart around a small enclosure. Its high prominence and rocky terrain made it naturally defensible with minimal construction.', 'West of Porthmadog, the 263 m hill of Moel y Gest is crowned by a hillfort of looping walls and a citadel, its entrance set back where an enemy would stay unseen until close at hand.', 'teaser-card-s014:8d416cb3-e799-4990-96a9-50a70fde39c2:card_description', 'teaser-card-s014 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '939a08e54b15700d7c7719f3190f07e2df3764f72135781b99932d8431e566c4|967dc9b3b04d67429b4a84321101bf95ad8cb0983bc9cabb86eff79d48e692d6|967dc9b3b04d67429b4a84321101bf95ad8cb0983bc9cabb86eff79d48e692d6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "West of Porthmadog, the 263 m hill of Moel y Gest is crowned by a hillfort of looping walls and a citadel, its entrance set back where an enemy would stay unseen until close at hand."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies west of Porthmadog [S1]; Moel y Gest is a hill 263 m high [S1]; the hill is crowned by a hillfort (at its summit) [S2]; the hillfort has loops of wall (a ''court'' system) [S3]; the hillfort has a citadel [S3]; the entrance lies where the defences are set back from the cliff [S4]; an approaching enemy would be unseen until close at hand at that entrance [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Moel y Gest is a hillfort site (the place is a hillfort) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; The hillfort crowns the hill (it is at the summit) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; Moel y Gest is a hill west of Porthmadog [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; The site is in Wales (North Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; The hill is 263 m high [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; The hillfort has looping walls [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; The hillfort has a citadel [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; The entrance is set back (from the cliff) [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]; An approaching enemy would stay unseen until close at hand at the entrance [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gest]"}]'::jsonb),
    ('8d96a44c-dbe5-4d08-875f-fd67534ae9cb'::uuid, 'card_description', 'Built in the late 3rd century AD and rebuilt twice, this Romano-Celtic temple gained an internal screen after 367 AD before being abandoned. Finds suggest a dedication to Mercury.', 'On a promontory above the River Chew, Pagans Hill Roman Temple faced east, possibly built for Mercury. A well about 15 meters west of its foundations held an unusual sculpture of a dog.', 'teaser-card-s014:8d96a44c-dbe5-4d08-875f-fd67534ae9cb:card_description', 'teaser-card-s014 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '0f4fb13335c24c873f678212b753af642045030107ef67450260ae28a111f985|fb6c7668fdeb1a13775f2e68a54d72c4bf5595ea5f1675acedd92b7456639ee1|fb6c7668fdeb1a13775f2e68a54d72c4bf5595ea5f1675acedd92b7456639ee1', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a promontory above the River Chew, Pagans Hill Roman Temple faced east, possibly built for Mercury. A well about 15 meters west of its foundations held an unusual sculpture of a dog."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the temple stood on a promontory above (overlooking) the River Chew [S5]; the temple faced east [S2]; it was possibly built for (to) the god Mercury (hedged) [S2]; a well lay about 15 meters west of the temple foundations [S7]; the well held an unusual sculpture of a dog [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pagans Hill Roman Temple is a Roman (Romano-British / Romano-Celtic) temple, at Pagans Hill, Chew Stoke, Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Pagans_Hill_Roman_temple]; The temple stood on a promontory above the River Chew [SUPPORTED: https://en.wikipedia.org/wiki/Pagans_Hill_Roman_temple]; The temple faced east [SUPPORTED: https://en.wikipedia.org/wiki/Pagans_Hill_Roman_temple]; It was possibly built for (dedicated to) Mercury [SUPPORTED: https://en.wikipedia.org/wiki/Pagans_Hill_Roman_temple]; A well about 15 meters west of the temple foundations held an unusual sculpture of a dog [SUPPORTED: https://en.wikipedia.org/wiki/Pagans_Hill_Roman_temple]"}]'::jsonb),
    ('8e131607-f575-485f-8115-275c68dda764'::uuid, 'card_description', 'A massive Iron Age ditch 30 metres wide and 10 metres deep running for nearly a mile. It may have served as a tribal boundary rather than a military fortification.', 'At the northern edge of St Albans, Beech Bottom Dyke runs almost a mile between banks on both sides, a ditch up to 30 m wide and 10 m deep, built probably between 5 and 40 AD.', 'teaser-card-s014:8e131607-f575-485f-8115-275c68dda764:card_description', 'teaser-card-s014 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '44d1582aa18f1f7bb27aa806c329ba3d20a3ea49802b1b2402577f37f3a8ca74|ce1389c77e9a4386a0aa9ecf037e68e450874e2e3206eaeea3299b12dd643906|ce1389c77e9a4386a0aa9ecf037e68e450874e2e3206eaeea3299b12dd643906', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At the northern edge of St Albans, Beech Bottom Dyke runs almost a mile between banks on both sides, a ditch up to 30 m wide and 10 m deep, built probably between 5 and 40 AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the dyke lies at the northern edge of St Albans [S1]; it runs for almost a mile [S1]; it is a ditch flanked by banks on both sides [S1]; the ditch is up to 30 m wide [S2]; the ditch is 10 m deep [S2]; it was built, probably between 5 and 40 AD [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Beech Bottom Dyke is a large ditch (a dyke, an earthwork) [SUPPORTED: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]; It lies at the northern edge of St Albans [SUPPORTED: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]; It runs for almost a mile [SUPPORTED: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]; It is flanked by banks on both sides [SUPPORTED: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]; The ditch is up to 30 m wide [SUPPORTED: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]; The ditch is 10 m deep [SUPPORTED: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]; It was built probably between 5 and 40 AD [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Beech_Bottom_Dyke]"}]'::jsonb),
    ('8f34775c-ca69-41e8-9517-35005cdc21b8'::uuid, 'card_description', 'The site features a group of circles including one with 41 small stones and a fallen stone 150 cm high at the south, with another of the same height outside the circle to the north.', 'Aughlish holds at least six stone circles and two stone rows. In one ring of 41 small stones, a fallen stone 150 cm high lies at the south, another as tall outside it to the north.', 'teaser-card-s014:8f34775c-ca69-41e8-9517-35005cdc21b8:card_description', 'teaser-card-s014 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'aae64d155a44c05f3d32f337d5c961da65c8108ef9a99b46f07d1d5c8db59aa6|de9d4f553f799b94983a4aa4cc69325733c94886c6ea6fedad9cbeb4da1b3964|de9d4f553f799b94983a4aa4cc69325733c94886c6ea6fedad9cbeb4da1b3964', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aughlish holds at least six stone circles and two stone rows. In one ring of 41 small stones, a fallen stone 150 cm high lies at the south, another as tall outside it to the north."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site holds at least six stone circles [S1]; the site holds two stone rows [S1]; one ring has 41 small stones [S2]; a fallen stone 150 cm high lies at the south of that ring [S2]; another stone of the same height lies outside the circle to the north [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aughlish is a site of stone circles (a stone circle site, a townland in County Londonderry, Northern Ireland) [SUPPORTED: https://en.wikipedia.org/wiki/Aughlish]; Aughlish holds at least six stone circles [SUPPORTED: https://en.wikipedia.org/wiki/Aughlish]; Aughlish holds two stone rows [SUPPORTED: https://en.wikipedia.org/wiki/Aughlish]; One ring has 41 small stones [SUPPORTED: https://en.wikipedia.org/wiki/Aughlish]; In that ring a fallen stone 150 cm high lies at the south [SUPPORTED: https://en.wikipedia.org/wiki/Aughlish]; Another stone of the same height (150 cm) stands outside the ring to the north [SUPPORTED: https://en.wikipedia.org/wiki/Aughlish]"}]'::jsonb),
    ('8f8d1ce5-3527-4c35-925f-579e6dc51784'::uuid, 'card_description', 'The University of Sydney''s Pella Excavation Project discovered at Tabaqat Fahl the remains of Neolithic housing dated to circa 6000 BCE.', 'By a rich water source in the foothills of the Jordan Valley, Pella holds the remains of Neolithic houses from circa 6000 BCE and the massive mud-brick walls of its city of circa 1800 BCE.', 'teaser-card-s014:8f8d1ce5-3527-4c35-925f-579e6dc51784:card_description', 'teaser-card-s014 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '699ca8de3e824a22e1a9fb1a4bf779de652cb5f2cd08dbfdbca58807d2e8a892|3f18ae968c4a6e4c0aaaabd94c548e8a06ab310be5c21f9bc20e2bcd86ba0a08|3f18ae968c4a6e4c0aaaabd94c548e8a06ab310be5c21f9bc20e2bcd86ba0a08', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "By a rich water source in the foothills of the Jordan Valley, Pella holds the remains of Neolithic houses from circa 6000 BCE and the massive mud-brick walls of its city of circa 1800 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pella lies near a rich water source [S2]; it lies in the foothills of the Jordan Valley [S2]; the site holds the remains of Neolithic houses [S3]; the Neolithic houses date to circa 6000 BCE [S3]; the city of circa 1800 BCE had massive mud-brick city walls [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pella is an ancient city (an ancient settlement with ruins) in Jordan [SUPPORTED: https://en.wikipedia.org/wiki/Pella,_Jordan]; Pella lies by a rich water source [SUPPORTED: https://en.wikipedia.org/wiki/Pella,_Jordan]; Pella lies in the foothills of the Jordan Valley [SUPPORTED: https://en.wikipedia.org/wiki/Pella,_Jordan]; Pella holds the remains of Neolithic houses from circa 6000 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Pella,_Jordan]; Pella''s city of circa 1800 BCE had massive mud-brick walls [SUPPORTED: https://en.wikipedia.org/wiki/Pella,_Jordan]"}]'::jsonb),
    ('9066c343-918a-45ca-b449-b3642e924c2b'::uuid, 'card_description', 'A seven-tiered adobe pyramid built by the Lima culture around 200-700 AD. Elite clergy who governed surrounding valleys used it for religious ceremonies.', 'In central Lima rises Huaca Pucllana, a great adobe and clay pyramid of seven staggered platforms, where deep pits once held offerings of fish and marine life to win the favor of the gods.', 'teaser-card-s014:9066c343-918a-45ca-b449-b3642e924c2b:card_description', 'teaser-card-s014 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '83fd80f0709e072079b4d3a148ec14d3f0e1deaa7a1d6b1d67a19d889acc7350|2bb44896d64db12bb94a93a1b31c335d40f1a4aebc81028e5c4c72057336e425|2bb44896d64db12bb94a93a1b31c335d40f1a4aebc81028e5c4c72057336e425', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In central Lima rises Huaca Pucllana, a great adobe and clay pyramid of seven staggered platforms, where deep pits once held offerings of fish and marine life to win the favor of the gods."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Huaca Pucllana is in central Lima [S1]; it is a great adobe and clay pyramid [S1]; it is built from seven staggered platforms [S1]; deep pits there once held offerings of fish and other marine life [S4]; the offerings were made to win the favor of the gods [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Huaca Pucllana is a pyramid site in central Lima, Peru (Miraflores district) [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Pucllana]; The pyramid is built of adobe and clay [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Pucllana]; The pyramid is built from seven staggered platforms [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Pucllana]; There were deep pits at the site where offerings were made [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Pucllana]; The offerings in the pits were of fish and marine life [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Pucllana]; The offerings were made to win the favor of the gods [SUPPORTED: https://en.wikipedia.org/wiki/Huaca_Pucllana]"}]'::jsonb),
    ('9072416f-69c6-4c4a-a5d3-6981eb899114'::uuid, 'card_description', 'The Giant''s Church at Kastelli is a rectangular stone enclosure measuring around 60 by 35 metres.', 'When built, Kastelli Giant''s Church would have stood on a rocky shoreline: a stone enclosure of around 60 by 35 metres, its walls seven metres wide, ringed by more than twenty cairns.', 'teaser-card-s014:9072416f-69c6-4c4a-a5d3-6981eb899114:card_description', 'teaser-card-s014 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '0b8afc1d67becdf6a8e1f1ea746f1a4eab58d077b242e85218c9230b1d391c18|8e732ea3fadf3eee625c329758aa65d6f49fb8020fdff67e18dceccec59b2794|8e732ea3fadf3eee625c329758aa65d6f49fb8020fdff67e18dceccec59b2794', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "When built, Kastelli Giant''s Church would have stood on a rocky shoreline: a stone enclosure of around 60 by 35 metres, its walls seven metres wide, ringed by more than twenty cairns."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "when built, it would have stood on a rocky shoreline (hedged) [S6]; it is a stone enclosure [S1, S4]; the enclosure measures around 60 by 35 metres [S4]; its walls are seven metres wide [S5]; it is surrounded by more than twenty cairns [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Kastelli Giant''s Church is a prehistoric stone enclosure near Pattijoki, Finland [SUPPORTED: https://en.wikipedia.org/wiki/Kastelli_Giant%27s_Church]; The enclosure measures around 60 by 35 metres [SUPPORTED: https://en.wikipedia.org/wiki/Kastelli_Giant%27s_Church]; The walls are seven metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Kastelli_Giant%27s_Church]; The enclosure is surrounded by more than twenty cairns [SUPPORTED: https://en.wikipedia.org/wiki/Kastelli_Giant%27s_Church]; When built the enclosure would have stood on a rocky shoreline [SUPPORTED: https://en.wikipedia.org/wiki/Kastelli_Giant%27s_Church]"}]'::jsonb),
    ('90a0c184-5830-45a7-a5ab-f82191dc0c23'::uuid, 'card_description', 'A chain of Iron Age earthworks stretching across Dorset. Each fort guarded a section of the landscape in what appears to be a coordinated defensive line.', 'On the north bank of the River Stour, the Iron Age hillfort of Dudsbury Camp encloses about 3 hectares; at its best-preserved corner the outer rampart rises over 5 metres above the ditch.', 'teaser-card-s014:90a0c184-5830-45a7-a5ab-f82191dc0c23:card_description', 'teaser-card-s014 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '6b50a370079bacbdf553272fff5def9c95aa06dd5033bd06b2090f47a18ed940|f440c7639dbf1fc858045907dc78f07f25493ffb821217fcbc945f1764d11a0f|f440c7639dbf1fc858045907dc78f07f25493ffb821217fcbc945f1764d11a0f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the north bank of the River Stour, the Iron Age hillfort of Dudsbury Camp encloses about 3 hectares; at its best-preserved corner the outer rampart rises over 5 metres above the ditch."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies on the north bank of the River Stour [S3]; Dudsbury Camp is an Iron Age hillfort [S3]; the defences enclose about 3 hectares [S4]; the best-preserved portion is near a corner (the southwest corner) [S6]; the outer rampart there rises over 5 metres above the ditch (bottom) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Dudsbury Camp is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Dudsbury_Camp]; The hillfort lies on the north bank of the River Stour [SUPPORTED: https://en.wikipedia.org/wiki/Dudsbury_Camp]; The defences enclose an area of about 3 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Dudsbury_Camp]; The best-preserved part of the defences lies near the southwest corner [SUPPORTED: https://en.wikipedia.org/wiki/Dudsbury_Camp]; At the best-preserved corner the outer rampart rises over 5 metres above the ditch [SUPPORTED: https://en.wikipedia.org/wiki/Dudsbury_Camp]; The outer rampart at the best-preserved portion rises 19 ft (about 5.8 m) above the bottom of the ditch [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO6225]"}]'::jsonb),
    ('9116c105-f7ac-4f02-8ea4-b724c68c9464'::uuid, 'card_description', 'Objects discovered from the time of Roman rule in Heraclea are votive monuments, a portico, thermae, a theatre and town walls.', NULL, 'teaser-card-s014:9116c105-f7ac-4f02-8ea4-b724c68c9464:card_description', 'teaser-card-s014 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||a16031bf357c12fdf853e1e1534a22dec46d4b4fa6f68b1bf608d8579cf50197', '[{"source": "lane WB run wb-ws-2026-09-27-01: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The web check contradicts: All three naves of the Great Basilica are covered with rich floral and figurative mosaics (https://muzejbitola.mk/en/mosaic-nartex/: \"The oldest Early-Christianity mosaics are represented by geometric motifs (loops, diamond cross, crossed circles), such as mosaics of the central aisle and deaconry of the Great Basilica\"); The web check could not prove: Heraclea Lyncestis is an ancient Greek city in Macedon (central claim: a city/settlement)"}]'::jsonb),
    ('915e58a4-967c-4d0f-b1d7-c4997ef1438a'::uuid, 'card_description', 'Capital of the Paeligni, chosen in 90 BC as the rebel capital during the Social War. For a brief moment, this small city challenged Roman supremacy.', 'In the valley of the Aternus, Corfinium, capital of the Paeligni, stood as a strong fortress: the only place to offer any effective resistance to Caesar during his advance through Italy.', 'teaser-card-s014:915e58a4-967c-4d0f-b1d7-c4997ef1438a:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'd19985205ace4d095e398f3a85007bf294d7a473dea8b0673aa135a22453e86c|f09ed114626fc1649738597d28725ff3f1139221a36b5013d5d98ae4737f8823|f09ed114626fc1649738597d28725ff3f1139221a36b5013d5d98ae4737f8823', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the valley of the Aternus, Corfinium, capital of the Paeligni, stood as a strong fortress: the only place to offer any effective resistance to Caesar during his advance through Italy."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Corfinium lay in the valley of the Aternus [S2]; it was the capital of the Paeligni [S2]; it was a strong fortress [S4]; it was the only place to offer any effective resistance to Caesar during his advance through Italy [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Corfinium was an ancient city, near modern Corfinio (Abruzzo) [SUPPORTED: https://en.wikipedia.org/wiki/Corfinium]; Corfinium was the capital of the Paeligni [SUPPORTED: https://en.wikipedia.org/wiki/Corfinium]; Corfinium lay in the valley of the Aternus [SUPPORTED: https://en.wikipedia.org/wiki/Corfinium]; Corfinium was a strong fortress [SUPPORTED: https://en.wikipedia.org/wiki/Corfinium]; It was the only place to offer any effective resistance to Caesar during his advance through Italy [SUPPORTED: https://en.wikipedia.org/wiki/Corfinium]"}]'::jsonb),
    ('918025af-8cfa-47db-a273-b4b715590e0c'::uuid, 'card_description', 'Tallest surviving broch in existence, built around 300 BC on Mousa in Shetland. Among the best-preserved Prehistoric structures in Europe, it still stands to its full original height.', 'On Mousa in Shetland rises the Broch of Mousa, the tallest broch still standing. Thought built circa 300 BC, it was besieged by Earl Harald Maddadsson in 1153, says the Orkneyinga Saga.', 'teaser-card-s014:918025af-8cfa-47db-a273-b4b715590e0c:card_description', 'teaser-card-s014 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '926da99fae4d379a093374b41671492c33a34593da98f1e9708b968b81dd390a|7565b920e14dd746757354d9955a0562c807af0bce95010f2556f5d10eaf39a6|7565b920e14dd746757354d9955a0562c807af0bce95010f2556f5d10eaf39a6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Mousa in Shetland rises the Broch of Mousa, the tallest broch still standing. Thought built circa 300 BC, it was besieged by Earl Harald Maddadsson in 1153, says the Orkneyinga Saga."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Broch of Mousa is on Mousa in Shetland [S2]; it is a broch [S1]; it is the tallest broch still standing [S3]; it is thought to have been built circa 300 BC (hedged) [S4]; it was besieged by Earl Harald Maddadsson [S6]; the siege was in 1153 [S6]; the siege is told by the Orkneyinga Saga [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Broch of Mousa is a broch, an Iron Age round tower [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Mousa]; It stands on the island of Mousa [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Mousa]; Mousa is in Shetland [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Mousa]; It is the tallest broch still standing [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Mousa]; It is thought to have been built circa 300 BC [SUPPORTED: https://www.historicenvironment.scot/visit/all/mousa-broch/]; The broch was besieged by Earl Harald Maddadsson [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Mousa]; The siege took place in 1153 [SUPPORTED: https://www.historicenvironment.scot/visit/all/mousa-broch/history-and-stories/]; The siege is recounted in the Orkneyinga Saga [SUPPORTED: https://www.historicenvironment.scot/visit/all/mousa-broch/history-and-stories/]"}]'::jsonb),
    ('931415bf-1cf2-4132-89ec-10b88eadf5d1'::uuid, 'card_description', 'Positioned 204 metres above sea level near the village of Membury in Devon, this hillfort commands sightlines across both the Yarty and Axe valleys — key corridors through the landscape below.', 'Above the village of Membury in Devon, the Iron Age hillfort of Membury Castle holds a commanding hilltop some 204 metres above sea level, with views across the Yarty and Axe valleys.', 'teaser-card-s014:931415bf-1cf2-4132-89ec-10b88eadf5d1:card_description', 'teaser-card-s014 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '2f09d603fafd3e7ecfd3d93868cba2110d7c698c6e24d6d42bf99ac6e781fbde|211e250923668b5ac14945543382be0680ab1b272a6e8ba609df289ee339c12c|211e250923668b5ac14945543382be0680ab1b272a6e8ba609df289ee339c12c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the village of Membury in Devon, the Iron Age hillfort of Membury Castle holds a commanding hilltop some 204 metres above sea level, with views across the Yarty and Axe valleys."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site lies above the village of Membury in Devon [S1]; Membury Castle is an Iron Age hillfort [S1]; the fort occupies a commanding hilltop position [S2]; the hilltop is some 204 metres above sea level [S2]; it has views across the Yarty and Axe valleys [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Membury Castle is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Membury_Castle]; The hillfort lies above the village of Membury [SUPPORTED: https://en.wikipedia.org/wiki/Membury_Castle]; Membury is in Devon [SUPPORTED: https://en.wikipedia.org/wiki/Membury,_Devon]; The fort holds a commanding hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Membury_Castle]; The hilltop is some 204 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Membury_Castle]; The hilltop has views across the Yarty valley [SUPPORTED: https://en.wikipedia.org/wiki/Membury_Castle]; The hilltop has views across the Axe valley [SUPPORTED: https://en.wikipedia.org/wiki/Membury_Castle]"}]'::jsonb),
    ('93d28b0d-2eba-440b-97a0-2bf291232dd5'::uuid, 'card_description', 'Univallate oval fort above the River Lynher in Cornwall, measuring roughly 275 by 170 metres and enclosing 2.5 hectares. Owned by the National Trust and a scheduled ancient monument.', 'On a steep hill above the River Lynher, the Iron Age hillfort of Cadson Bury encloses an oval of about 2.5 hectares, yet within its rampart there are no traces of house platforms.', 'teaser-card-s014:93d28b0d-2eba-440b-97a0-2bf291232dd5:card_description', 'teaser-card-s014 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'eed0522e4f23014376255756010d50dc009269c847c49fd372af5108b808de25|bdce584d13eac8ddffbbf20e3393737e43df845d3ea6a19c82202ac0b7b8ad3f|bdce584d13eac8ddffbbf20e3393737e43df845d3ea6a19c82202ac0b7b8ad3f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a steep hill above the River Lynher, the Iron Age hillfort of Cadson Bury encloses an oval of about 2.5 hectares, yet within its rampart there are no traces of house platforms."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the fort stands on a steep hill [S2]; the hill is above the River Lynher [S2]; Cadson Bury is an Iron Age hillfort [S1]; it encloses an oval [S4]; the enclosure covers about 2.5 hectares [S4]; there are no traces of house platforms within the enclosure [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cadson Bury is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Cadson_Bury]; The hillfort stands on a steep hill [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA100162]; The steep hill is above the River Lynher [SUPPORTED: https://en.wikipedia.org/wiki/Cadson_Bury]; The enclosure is an oval [SUPPORTED: https://en.wikipedia.org/wiki/Cadson_Bury]; The enclosure covers about 2.5 hectares [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA100162]; The hillfort has a rampart [SUPPORTED: https://en.wikipedia.org/wiki/Cadson_Bury]; Within the enclosure there are no traces of house platforms [SUPPORTED: https://en.wikipedia.org/wiki/Cadson_Bury]"}]'::jsonb),
    ('93dd77da-64ad-4947-96b3-8ead4d6c98c1'::uuid, 'card_description', 'A hilltop where over 250 pits filled with dismembered human and animal remains were found, dating to around 100 BC. The scale of ritual deposition here is unprecedented in Celtic Europe.', 'On Mormont, a hill in Vaud, a late La Tène cult site held pits filled with vessels, iron tools, jewelry, coins, animal and human remains. Reported as unprecedented in size and richness.', 'teaser-card-s014:93dd77da-64ad-4947-96b3-8ead4d6c98c1:card_description', 'teaser-card-s014 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'dcb899c478692481dd7a8071f1d9e2217dc2c5fb204f6e0ebf1366a9d4e215c2|2de8ed29e0835c3c303e5b90c55b7b56f8b3f6f71761e06daf487baccf74ea04|2de8ed29e0835c3c303e5b90c55b7b56f8b3f6f71761e06daf487baccf74ea04', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Mormont, a hill in Vaud, a late La Tène cult site held pits filled with vessels, iron tools, jewelry, coins, animal and human remains. Reported as unprecedented in size and richness."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Mormont is a hill in Vaud [S1]; the site is a cult site [S2]; the cult site dates to the late La Tène period [S2]; the site held pits with deposits [S2]; the deposits include vessels, iron tools, jewelry and coins [S3]; the deposits include animal and human remains [S3]; the site was reported as unprecedented in size and richness [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Mormont is a hill in Vaud (Switzerland) [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; On Mormont there is a cult site (central claim: a cult/sacrificial site of pits on a hill) [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The cult site dates to the late La Tène period [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The site held pits (filled with deposited goods) [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The pits held vessels among the deposited goods [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The pits held iron tools [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The pits held jewelry [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The pits held coins [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The pits held animal and human remains [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]; The site was reported as unprecedented in size and richness [SUPPORTED: https://en.wikipedia.org/wiki/Mormont]"}]'::jsonb),
    ('93f7a2e9-2d34-4ac7-bb22-9327d1897648'::uuid, 'card_description', 'A 7th-century BC temple with striking similarities to ancient Egyptian architecture, including an Egyptianised seated goddess. It sits halfway between Knossos and Gortyn.', 'On Crete, Prinias revealed a seventh-century BCE temple with striking similarities to Egyptian architecture, an Egyptianised seated goddess among them, and a singular frieze of horsemen.', 'teaser-card-s014:93f7a2e9-2d34-4ac7-bb22-9327d1897648:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '81c621718a63f7c3db65afd58cc8a18f72d278c94dd99e6b9072b608081c778a|36485bc3a3d4c83a91be595faecad21387102c73c6d4b2110bd63741f57ce795|36485bc3a3d4c83a91be595faecad21387102c73c6d4b2110bd63741f57ce795', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Crete, Prinias revealed a seventh-century BCE temple with striking similarities to Egyptian architecture, an Egyptianised seated goddess among them, and a singular frieze of horsemen."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Prinias is on Crete [S1]; the site revealed a seventh-century BCE temple [S1]; the temple has striking similarities to Egyptian architecture [S1]; an Egyptianised seated goddess is among those similarities [S1]; a singular frieze of horsemen is among the finds from Prinias [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Prinias is an archaeological site on Crete where a temple was unearthed [SUPPORTED: https://www.ancientworldmagazine.com/articles/armed-riders-crete-reliefs-temple-prinias/]; The Prinias temple dates to the seventh century BCE [SUPPORTED: https://www.ancientworldmagazine.com/articles/armed-riders-crete-reliefs-temple-prinias/]; The temple shows striking similarities to Egyptian architecture [SUPPORTED: https://en.wikipedia.org/wiki/Prinias]; The site revealed an Egyptianised seated goddess [SUPPORTED: https://en.wikipedia.org/wiki/Prinias]; The temple had a frieze of horsemen [SUPPORTED: http://odysseus.culture.gr/h/4/eh430.jsp?obj_id=7927]; The frieze of horsemen is singular (unique) [SUPPORTED: https://en.wikipedia.org/wiki/Prinias]"}]'::jsonb),
    ('94f496b6-5e15-4a5a-9bd2-0cb1885864bf'::uuid, 'card_description', NULL, 'At Bartlow Hills the tallest barrow rises 15 metres, the largest Roman barrow north of the Alps. Excavators found walled graves with cremains in glass vessels, kept in large wooden chests.', 'teaser-card-s014:94f496b6-5e15-4a5a-9bd2-0cb1885864bf:card_description', 'teaser-card-s014 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7e8693848c01c2ec775df0b86d24c590989622b22e60f17802d39cea32d32982|d5b670ab5b4bcacaf04e307be9f92bd2a22644b22c24dace7bb071a7af909586|d5b670ab5b4bcacaf04e307be9f92bd2a22644b22c24dace7bb071a7af909586', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Bartlow Hills the tallest barrow rises 15 metres, the largest Roman barrow north of the Alps. Excavators found walled graves with cremains in glass vessels, kept in large wooden chests."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the tallest barrow at Bartlow Hills is 15 metres high [S2]; the tallest barrow is the largest Roman barrow north of the Alps [S2]; excavators found walled graves [S4]; the graves held cremains in glass vessels [S4]; the glass vessels were kept in large wooden chests [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bartlow Hills is a Roman barrow (tumuli) cemetery at Bartlow, in England [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow_Hills]; The tallest barrow at Bartlow Hills is 15 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow_Hills]; The tallest barrow is the largest Roman barrow north of the Alps [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow_Hills]; Excavators found walled graves containing cremains (cremated human remains) [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow_Hills]; The cremains were found within glass vessels [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow_Hills]; The glass vessels were stored in large wooden chests [SUPPORTED: https://en.wikipedia.org/wiki/Bartlow_Hills]"}]'::jsonb),
    ('953e0154-1d30-4502-953d-4de1ff7bda62'::uuid, 'card_description', 'The main sight on the small island is the Southcairn, a 20 metre long chambered cairn dating from approx. 3000 BC on whose stones one can find ancient carvings.', 'On a tiny uninhabited Orkney island, a trapdoor leads into the Holm of Papa Chambered Cairn, a 20 metre long communal tomb from approximately 3000 BC with ancient carvings on its stones.', 'teaser-card-s014:953e0154-1d30-4502-953d-4de1ff7bda62:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'bcc37d11a2401f13243e5136dca90c038c826a7e16380bea1cb921e3a4ba6cbb|82c2a84a6d322186df3b07a68f04bcda91f2415f80b799097c4e4f826001b2d7|82c2a84a6d322186df3b07a68f04bcda91f2415f80b799097c4e4f826001b2d7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a tiny uninhabited Orkney island, a trapdoor leads into the Holm of Papa Chambered Cairn, a 20 metre long communal tomb from approximately 3000 BC with ancient carvings on its stones."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the cairn lies on a tiny island in Orkney [S1]; the island is uninhabited [S1]; the cairn is entered by a trapdoor [S4]; the cairn is 20 metres long [S2]; the cairn was a communal tomb (burial place of an ancient community) [S3]; the cairn dates from approximately 3000 BC [S2]; ancient carvings are found on its stones [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Holm of Papa Chambered Cairn is a chambered cairn (a tomb) on the Holm of Papa, an island of Orkney, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]; The cairn stands on a tiny uninhabited island of Orkney [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]; A trapdoor leads into the cairn (it is entered by a trapdoor from above) [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]; The cairn is 20 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]; The cairn dates from approximately 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]; The cairn is a communal tomb (a communal burial place of an ancient community) [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]; There are ancient carvings on the stones of the cairn [SUPPORTED: https://en.wikipedia.org/wiki/Holm_of_Papa_Westray]"}]'::jsonb),
    ('95ef632b-03af-4f8d-8881-0b59d0668d45'::uuid, 'card_description', 'Aquae Arnemetiae was at the intersection of two main Roman roads: Batham Gate and The Street.', 'Aquae Arnemetiae was centred on natural warm springs: a small town of Roman Britannia, with a bath at its main thermal spring and a temple to the water deity Arnemetia.', 'teaser-card-s014:95ef632b-03af-4f8d-8881-0b59d0668d45:card_description', 'teaser-card-s014 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '56a6918ef21fbadbc71095e6fdffcb400071c8d5c35417dbde12bfddaf1f929a|d7fda8adfb9ec01abb5bfc4e5ed6de9d376f366ed3e7fd1dcb52702b41254085|d7fda8adfb9ec01abb5bfc4e5ed6de9d376f366ed3e7fd1dcb52702b41254085', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aquae Arnemetiae was centred on natural warm springs: a small town of Roman Britannia, with a bath at its main thermal spring and a temple to the water deity Arnemetia."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the settlement was centred on natural warm springs [S2]; it was a small town [S1]; it lay in Roman Britannia [S1]; it had a bath at its main thermal spring [S4]; it had a temple dedicated to the water deity Arnemetia [S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aquae Arnemetiae was a small town in the Roman province of Britannia (today Buxton, Derbyshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Aquae_Arnemetiae]; The settlement was centred on natural warm springs [SUPPORTED: https://en.wikipedia.org/wiki/Aquae_Arnemetiae]; The town had a Roman bath (it was one of only two Roman bath towns in Britain) [SUPPORTED: https://en.wikipedia.org/wiki/Aquae_Arnemetiae]; The bath stood at the town''s main thermal spring [SUPPORTED: https://en.wikipedia.org/wiki/Aquae_Arnemetiae]; The town had a temple, whose base was documented overlooking the baths and springs [SUPPORTED: https://en.wikipedia.org/wiki/Aquae_Arnemetiae]; The temple was dedicated to Arnemetia, a water deity [SUPPORTED: https://en.wikipedia.org/wiki/Aquae_Arnemetiae]"}]'::jsonb),
    ('9624278c-1080-4a2a-ae2e-11829bda299a'::uuid, 'card_description', 'The building was used to house many lavish votive offerings given to the priests for presentation to Apollo.', 'Silver and gold from Siphnos built the Siphnian Treasury at Delphi, the first religious structure made entirely of marble. On its east pediment, Heracles steals Apollo''s tripod.', 'teaser-card-s014:9624278c-1080-4a2a-ae2e-11829bda299a:card_description', 'teaser-card-s014 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '0cd64475029cf2cd37d8df68476a29ddf3911d59fa31ecbc9a7eb346da549bbf|f81fe42f741be18d08f1be835f24dd3e6e361cb54bba807401a42a3ac9f7d44b|f81fe42f741be18d08f1be835f24dd3e6e361cb54bba807401a42a3ac9f7d44b', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Silver and gold from Siphnos built the Siphnian Treasury at Delphi, the first religious structure made entirely of marble. On its east pediment, Heracles steals Apollo''s tripod."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Siphnians'' wealth from silver and gold mines paid for the treasury [S3]; the treasury stood at Delphi [S1]; it was the first religious structure made entirely of marble [S3]; its east pediment shows Heracles stealing Apollo''s tripod [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Siphnian Treasury was a treasury building at the sanctuary of Delphi, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Siphnian_Treasury]; It was built for the city-state of Siphnos (Siphnos erected it) [SUPPORTED: https://en.wikipedia.org/wiki/Siphnian_Treasury]; It was paid for with silver and gold from Siphnos (wealth from the island''s silver and gold mines) [SUPPORTED: https://en.wikipedia.org/wiki/Siphnian_Treasury]; The treasury was made entirely of marble [SUPPORTED: https://www.delphimuseum.gr/2025/03/the-treasury-of-siphnians.html]; It was the first religious structure made entirely of marble [SUPPORTED: https://en.wikipedia.org/wiki/Siphnian_Treasury]; The treasury has an east pediment with sculpture [SUPPORTED: https://en.wikipedia.org/wiki/Siphnian_Treasury]; The east pediment shows Heracles stealing Apollo''s tripod [SUPPORTED: https://en.wikipedia.org/wiki/Siphnian_Treasury]"}]'::jsonb),
    ('9711aeef-a3b2-45ad-8f2c-6c8f033eb9ec'::uuid, 'card_description', 'A Roman market whose columns are riddled with holes bored by marine molluscs — proof that volcanic ground movement submerged and re-raised the building multiple times over centuries.', 'Three marble columns of the Macellum of Pozzuoli bear a band of borings left by marine molluscs, a sign they stood upright over centuries as the site sank below sea level, then re-emerged.', 'teaser-card-s014:9711aeef-a3b2-45ad-8f2c-6c8f033eb9ec:card_description', 'teaser-card-s014 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '172d3c1d3bda7e29f9b9f9cdf4d126c5063cafa2c78155a6e3c88aee42af92c9|8dc75e8dd70c520d55f387262c9cb567fcf67d0a0329dd8350d092d6941a5284|8dc75e8dd70c520d55f387262c9cb567fcf67d0a0329dd8350d092d6941a5284', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Three marble columns of the Macellum of Pozzuoli bear a band of borings left by marine molluscs, a sign they stood upright over centuries as the site sank below sea level, then re-emerged."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "three marble columns stand at the Macellum of Pozzuoli [S3]; the columns bear a band of borings [S3]; the borings were left by marine molluscs [S3]; the borings indicate the columns stood upright over centuries [S3]; the site sank below sea level and then re-emerged [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Macellum of Pozzuoli is the macellum (market building) of Roman Puteoli, now Pozzuoli in southern Italy [SUPPORTED: https://en.wikipedia.org/wiki/Macellum_of_Pozzuoli]; Three standing marble columns of the macellum survive [SUPPORTED: https://en.wikipedia.org/wiki/Macellum_of_Pozzuoli]; The three marble columns bear a band of borings left by marine molluscs [SUPPORTED: https://en.wikipedia.org/wiki/Macellum_of_Pozzuoli]; The borings are a sign that the columns remained upright over centuries [SUPPORTED: https://en.wikipedia.org/wiki/Macellum_of_Pozzuoli]; The site sank below sea level while the columns stood [SUPPORTED: https://en.wikipedia.org/wiki/Macellum_of_Pozzuoli]; The site then re-emerged from the sea [SUPPORTED: https://en.wikipedia.org/wiki/Macellum_of_Pozzuoli]"}]'::jsonb),
    ('9789696d-6670-42d8-a76a-bd73fd3ca2c0'::uuid, 'card_description', 'A 4th-century Roman bathhouse converted into a church — the oldest building still standing in its city. Medieval frescoes cover walls that once sweated with steam.', 'Built as Roman baths in the early 4th century CE, the red brick rotunda of the Church of Saint George is crowned by frescoes of 22 prophets over two metres tall, long hidden under paint.', 'teaser-card-s014:9789696d-6670-42d8-a76a-bd73fd3ca2c0:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '3d841f3fd4bf4fb70196d95b139e39d9d7686632a80ed699ffa03471417f0f43|6e980ed8d593e77a717c3f48d5b9e525cf2cd0ff3b93d6357baa8948f1417abf|6e980ed8d593e77a717c3f48d5b9e525cf2cd0ff3b93d6357baa8948f1417abf', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Built as Roman baths in the early 4th century CE, the red brick rotunda of the Church of Saint George is crowned by frescoes of 22 prophets over two metres tall, long hidden under paint."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the building was built as Roman baths [S2]; it was built in the early 4th century CE [S2]; it is a red brick rotunda [S1]; frescoes crown the dome [S5]; the frescoes show 22 prophets [S5]; the prophets are over two metres tall [S5]; the frescoes were long hidden under paint (painted over in the Ottoman era, only uncovered in the 20th century) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Church of Saint George is a rotunda church in Sofia, Bulgaria (central claim: a late antique rotunda church, formerly Roman baths) [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; The building is a rotunda (cylindrical domed structure on a square base) [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; The rotunda is of red brick [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; It was built as Roman baths [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; It was built in the early 4th century CE [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; The dome is crowned by frescoes of 22 prophets [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; The prophet frescoes are over two metres tall [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]; The prophet frescoes were long hidden under paint (painted over in the Ottoman era, uncovered only in the 20th century) [SUPPORTED: https://en.wikipedia.org/wiki/Church_of_Saint_George,_Sofia]"}]'::jsonb),
    ('98e72c8a-806c-4a84-bdb6-0ba92ea20010'::uuid, 'card_description', 'Two Bronze Age barrows crown a prominent 244-meter hill west of Warminster — the hilltop was a burial place long before the Iron Age fort was raised around it.', 'Cley Hill holds a large Iron Age hill fort and two bowl barrows. In 1812 Sir Richard Hoare tried to excavate the mound at its top and found it looted by grave robbers.', 'teaser-card-s014:98e72c8a-806c-4a84-bdb6-0ba92ea20010:card_description', 'teaser-card-s014 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '5dc3409a4c35b083aa5cfb2a714c695dc54c0e79ca89458d74414f8d9587574e|a3d759dcd22eb95500eda93ca5ef3133bb72b720838ecd1fd00f7d40f4899fcb|a3d759dcd22eb95500eda93ca5ef3133bb72b720838ecd1fd00f7d40f4899fcb', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cley Hill holds a large Iron Age hill fort and two bowl barrows. In 1812 Sir Richard Hoare tried to excavate the mound at its top and found it looted by grave robbers."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cley Hill has a large Iron Age hill fort [S3]; Cley Hill has two bowl barrows [S3]; in 1812 Sir Richard Hoare tried to excavate the mound at the top of the hill [S4]; he found the mound looted by grave robbers [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cley Hill is a hill in England (Wiltshire) with archaeological features (central claim: a hill site holding a hill fort and barrows) [SUPPORTED: https://en.wikipedia.org/wiki/Cley_Hill]; Cley Hill holds a large Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Cley_Hill]; Cley Hill holds two bowl barrows [SUPPORTED: https://en.wikipedia.org/wiki/Cley_Hill]; In 1812 Sir Richard Hoare tried to excavate the mound at the top of the hill [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Cley_Hill]; Hoare found the mound had been looted by grave robbers [SUPPORTED: https://en.wikipedia.org/wiki/Cley_Hill]"}]'::jsonb),
    ('9949dec1-5552-40ad-b5b5-fb9c29bff468'::uuid, 'card_description', 'A hilltop citadel occupied from 300 to 1200 AD whose builders remain debated. A massive stone stairway climbs the terraced site, and a votive pyramid holds racks of human bones.', 'La Quemada developed between 300 and 1200 AD, its sunken patios and altar-pyramids all built of rhyolite slabs. A speculation of 1780 began the belief it is the mythical Seven Caves.', 'teaser-card-s014:9949dec1-5552-40ad-b5b5-fb9c29bff468:card_description', 'teaser-card-s014 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '3ec93d19848b016d95eca9c7c7c0af281437d2561e6198c8e872223af4e23255|1618054c13f81242f9a89bae21e4416b9b503e6ac89573ec9f30f7247fac927d|1618054c13f81242f9a89bae21e4416b9b503e6ac89573ec9f30f7247fac927d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Quemada developed between 300 and 1200 AD, its sunken patios and altar-pyramids all built of rhyolite slabs. A speculation of 1780 began the belief it is the mythical Seven Caves."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Quemada developed between 300 and 1200 AD [S5]; it has sunken patios and altar-pyramids [S6]; all its architectonic elements, including these, were built of rhyolite slabs [S7]; a speculation of 1780 began the belief that it is the mythical Seven Caves [S3, S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "La Quemada is an archaeological site (a Mesoamerican ceremonial and settlement complex on a hill) in Zacatecas, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/La_Quemada]; La Quemada developed between 300 and 1200 AD [SUPPORTED: https://en.wikipedia.org/wiki/La_Quemada]; The site has sunken patios and altar-pyramids [SUPPORTED: https://en.wikipedia.org/wiki/La_Quemada]; All its architectural elements were built of rhyolite slabs [SUPPORTED: https://en.wikipedia.org/wiki/La_Quemada]; In 1780 a speculation (Clavijero associating the site with Chicomoztoc) was made [SUPPORTED: https://en.wikipedia.org/wiki/La_Quemada]; That speculation originated the belief that La Quemada is the mythical Seven Caves [SUPPORTED: https://en.wikipedia.org/wiki/La_Quemada]"}]'::jsonb),
    ('99add2bd-b314-4bb9-885b-95f407b3b44e'::uuid, 'card_description', 'The fort was defended by two layers of ramparts to the west and north with escarpments on the eastern and southern slopes.', 'On wooded Holmbury Hill, 261 metres up in Surrey, an Iron Age hillfort''s inner ditches were some four metres deep and nine metres wide, earthworks perhaps symbolic as well as military.', 'teaser-card-s014:99add2bd-b314-4bb9-885b-95f407b3b44e:card_description', 'teaser-card-s014 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'd1f89dff237f39254a2cd935696ac0f2514a0fa8c450605ed422360e0222ff88|5567a541430993f0255daaebc659c8e50330a3a7099162c3bfab8815d21b28ae|5567a541430993f0255daaebc659c8e50330a3a7099162c3bfab8815d21b28ae', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On wooded Holmbury Hill, 261 metres up in Surrey, an Iron Age hillfort''s inner ditches were some four metres deep and nine metres wide, earthworks perhaps symbolic as well as military."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Holmbury Hill is wooded [S1]; it is 261 metres above sea level [S1, S6]; it lies in Surrey [S1]; it is the site of an Iron Age hillfort [S1]; the inner ditches were some four metres deep and nine metres wide [S4]; the earthworks perhaps had a symbolic function as well as a military one (hedged) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Holmbury Hill is the site of an Iron Age hillfort (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]; Holmbury Hill is wooded [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]; The hill is 261 metres up [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]; The hill is in Surrey [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]; The inner ditches were some four metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]; The inner ditches were some nine metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]; The earthworks may have been symbolic as well as military (uncertain function) [SUPPORTED: https://en.wikipedia.org/wiki/Holmbury_Hill]"}]'::jsonb),
    ('9a47c62e-0961-4e76-b253-a62b8d0bac87'::uuid, 'card_description', '1st-century AD Roman water chambers beneath Toledo, discovered in 1628. One large arched gallery feeds three parallel vaulted galleries that once supplied thermal baths at the Plaza de Amador.', 'Beneath Toledo, the Roman Remains under Alfonso X Street are arched galleries that fed water to a thermal bath from around the 1st century AD, hidden until 1628 and rediscovered in 1918.', 'teaser-card-s014:9a47c62e-0961-4e76-b253-a62b8d0bac87:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '997bc04fe66bd07dc096520f872bd77b42e39d22b0dce6a4bd5146508cd16162|77049085b2c9a82271b4e7023d73856b73b3707784c5116c8dc50d3cfbf466fb|77049085b2c9a82271b4e7023d73856b73b3707784c5116c8dc50d3cfbf466fb', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Beneath Toledo, the Roman Remains under Alfonso X Street are arched galleries that fed water to a thermal bath from around the 1st century AD, hidden until 1628 and rediscovered in 1918."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the remains lie beneath Toledo [S1]; the remains are arched galleries [S3]; they supplied water to a thermal bath [S2]; the thermal bath dates from around the 1st century AD [S2]; they were hidden until 1628 [S4]; they were rediscovered in 1918 [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Remains under Alfonso X Street are in the city of Toledo, Spain (central claim: Roman water-supply chambers of a thermal bath) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]; The remains lie beneath Alfonso X Street (Roman remains under the street) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]; The remains are arched galleries [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]; The chambers supplied (fed) water to a thermal bath [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]; The thermal bath dates from around the 1st century AD [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]; They were hidden until 1628 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]; They were rediscovered in 1918 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_remains_under_Alfonso_X_street]"}]'::jsonb),
    ('9aab078b-ef81-43a1-8169-235e5b22dd34'::uuid, 'card_description', 'Twenty-four enormous artificial caverns carved from sandstone over 2,000 years ago. No historical record mentions them — farmers stumbled on them in 1992 while draining a pond.', 'In June 1992, four farmers drained five small ponds and found them to be large manmade caverns: the Longyou Grottoes, 24 sandstone chambers with ceilings up to 30 m high.', 'teaser-card-s014:9aab078b-ef81-43a1-8169-235e5b22dd34:card_description', 'teaser-card-s014 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '5afc21f5fb2f96bf38fd768a21e476ff256f8623550a8794e9de6c716a076c16|e1fb140afecca8b90151810f263dee2bb1d554eac6bb025a84c022e974eee194|e1fb140afecca8b90151810f263dee2bb1d554eac6bb025a84c022e974eee194', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In June 1992, four farmers drained five small ponds and found them to be large manmade caverns: the Longyou Grottoes, 24 sandstone chambers with ceilings up to 30 m high."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "in June 1992 the caves were found [S2]; four farmers found them [S2]; the farmers drained five small ponds [S2]; the ponds turned out to be large manmade caverns [S2, S3]; the Longyou Grottoes are 24 sandstone chambers [S1]; ceilings reach up to 30 m high [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Longyou Grottoes (also called Longyou Caves) are a group of artificial, man-made caverns in Longyou County, Quzhou, Zhejiang Province, China [SUPPORTED: https://en.wikipedia.org/wiki/Longyou_Caves]; There are 24 chambers [SUPPORTED: https://longyou-caves.cn/en]; The chambers are cut in sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Longyou_Caves]; Ceilings are up to 30 m high [SUPPORTED: https://en.wikipedia.org/wiki/Longyou_Caves]; The caverns were found in June 1992 [SUPPORTED: https://en.wikipedia.org/wiki/Longyou_Caves]; The finders were four farmers (Wu Anai and three companions) [SUPPORTED: https://longyou-caves.cn/en/discovery]; The farmers drained five small ponds (Wikipedia''s wording; the official site says they first drained one pond and nearby ponds followed) [SUPPORTED: https://en.wikipedia.org/wiki/Longyou_Caves]; The ponds turned out to be large manmade caverns [SUPPORTED: https://en.wikipedia.org/wiki/Longyou_Caves]"}]'::jsonb),
    ('9ab9a6fa-2a4d-47db-8db4-237820a577d2'::uuid, 'card_description', NULL, 'Around 5500 BCE, the first settlers of Aigeira lived on its acropolis, leaving pottery that includes vessels likely used to make cheese. It was abandoned at the end of the Bronze Age.', 'teaser-card-s014:9ab9a6fa-2a4d-47db-8db4-237820a577d2:card_description', 'teaser-card-s014 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '750f555d6cdee98eb863dd7ef83b859dcf22a331e16d066156fefe52bdedb3f3|69471ff2a0e8fa9e6f2f7661fdb5bf93aab07f87e76b088ca7928e2b2e8b5c83|69471ff2a0e8fa9e6f2f7661fdb5bf93aab07f87e76b088ca7928e2b2e8b5c83', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Around 5500 BCE, the first settlers of Aigeira lived on its acropolis, leaving pottery that includes vessels likely used to make cheese. It was abandoned at the end of the Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "settlement at Aigeira began around 5500 BCE [S3]; the first settlers lived on the acropolis [S4]; they left pottery [S4]; the pottery includes vessels likely used to make cheese (hedged) [S4]; Aigeira was abandoned at the end of the Bronze Age [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aigeira is an ancient settlement with an acropolis, an archaeological site in Achaea, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Aigeira]; Settlement at Aigeira began around 5500 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Aigeira]; The first settlers lived on the acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Aigeira]; The pottery includes vessels likely used to make cheese [SUPPORTED: https://en.wikipedia.org/wiki/Aigeira]; Aigeira was abandoned at the end of the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Aigeira]; The abandonment was not final: occupation began again in the second half of the 8th century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Aigeira]"}]'::jsonb),
    ('9b543ec0-a5ab-49bd-abb3-183570b39989'::uuid, 'card_description', 'A Maya coastal city active from the 1st century through the Post-Classic period. It served as both a commercial hub and a port on the Caribbean trade routes.', 'On the Yucatán coast, the Maya port of Xelha served the city of Coba and was likely a point of exchange with other sea-navigating peoples between the 7th and 12th centuries.', 'teaser-card-s014:9b543ec0-a5ab-49bd-abb3-183570b39989:card_description', 'teaser-card-s014 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', 'ea0574222dfe1cf4aaa52b48b7fe527dd926742d71690a29052897d56b5145d4|bb8f35acecc98eea240cbc56bedbe77a7f67451522d54263cc167981841f2489|bb8f35acecc98eea240cbc56bedbe77a7f67451522d54263cc167981841f2489', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the Yucatán coast, the Maya port of Xelha served the city of Coba and was likely a point of exchange with other sea-navigating peoples between the 7th and 12th centuries."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xelha lies on the Yucatan coast [S1]; it is a Maya site [S1]; it was a port that served the city of Coba [S4]; it was likely a point of exchange with other sea-navigating peoples (hedged) [S5]; this exchange was between the 7th and 12th centuries [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xelha is a Maya port on the Yucatan coast (Quintana Roo, Mexico) [SUPPORTED: https://lugares.inah.gob.mx/en/node/4363]; Xelha is located on the coast of the Yucatan Peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Xelha]; Xelha served the Maya city of Coba as a port [SUPPORTED: https://en.wikipedia.org/wiki/Xelha]; Xelha was likely a point of exchange with other sea-navigating peoples [SUPPORTED: https://en.wikipedia.org/wiki/Xelha]; The exchange dated to between the 7th and 12th centuries [SUPPORTED: https://en.wikipedia.org/wiki/Xelha]"}]'::jsonb),
    ('9b682dd4-674c-4713-9cdc-55723a5f25bf'::uuid, 'card_description', 'Triangular in plan on a Quantock Hills spur, this univallate fort encloses 1.8 hectares. A linear outwork 120 m beyond the rampart and ditch adds a second defensive line to the north.', 'Named from words meaning Rough Hill, Ruborough Camp is an Iron Age hill fort on a Quantock spur, a triangle of 1.8 hectares ringed by a single rampart and ditch.', 'teaser-card-s014:9b682dd4-674c-4713-9cdc-55723a5f25bf:card_description', 'teaser-card-s014 (teaser-card): teaser card, 161 characters, checked PASS, web-verified VERIFIED', '011339c651cdef46f7ee66db89c72f72e17fda97582913a3be1fd0b9cd893cbd|a64727272d2a138c7262060a7843dbeaedf9d1503151007984318e34c6b0319a|a64727272d2a138c7262060a7843dbeaedf9d1503151007984318e34c6b0319a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Named from words meaning Rough Hill, Ruborough Camp is an Iron Age hill fort on a Quantock spur, a triangle of 1.8 hectares ringed by a single rampart and ditch."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the name comes from words meaning Rough Hill [S2]; Ruborough Camp is an Iron Age hill fort [S1]; it lies on a spur of the Quantock ridge [S1, S3]; the fort is triangular [S4]; it encloses 1.8 hectares [S4]; it has a single rampart and ditch [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Ruborough Camp is an Iron Age hill fort on the Quantock Hills in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Ruborough_Camp]; The name comes from words meaning Rough Hill [SUPPORTED: https://en.wikipedia.org/wiki/Ruborough_Camp]; The fort lies on a spur of the Quantock ridge [SUPPORTED: https://en.wikipedia.org/wiki/Ruborough_Camp]; The fort is triangular [SUPPORTED: https://en.wikipedia.org/wiki/Ruborough_Camp]; It is ringed by a single rampart and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Ruborough_Camp]; The enclosed area is 1.8 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Ruborough_Camp]"}]'::jsonb),
    ('9bf7ac31-4f48-4bbc-ad4b-cbef11d994b9'::uuid, 'card_description', 'The site shows occupation, in at least four phases, dating from the early Iron Age to the post-Roman period.', 'On an oval promontory above a tributary of the River Wansbeck, Huckhoe Settlement was lived in from the 6th century BC to the 6th century AD, once ringed by three oak palisades.', 'teaser-card-s014:9bf7ac31-4f48-4bbc-ad4b-cbef11d994b9:card_description', 'teaser-card-s014 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '3d4b0633380e0940d1bd9236bf6ad69f74a7867dc67593e5f1129226a98c2994|76e7e862477fff95d095d80711ab62dbc39768d9e811e61d7a8a1431a4c45dc4|76e7e862477fff95d095d80711ab62dbc39768d9e811e61d7a8a1431a4c45dc4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On an oval promontory above a tributary of the River Wansbeck, Huckhoe Settlement was lived in from the 6th century BC to the 6th century AD, once ringed by three oak palisades."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is on an oval promontory [S3]; the promontory is above a tributary of the River Wansbeck [S3]; the site was occupied from the 6th century BC to the 6th century AD [S2]; it was once ringed by three oak palisades [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Huckhoe Settlement is an archaeological site (a defended settlement) in Northumberland, England [SUPPORTED: https://en.wikipedia.org/wiki/Huckhoe_Settlement]; The site is on an oval promontory above a tributary of the River Wansbeck [SUPPORTED: https://en.wikipedia.org/wiki/Huckhoe_Settlement]; The site was occupied from the 6th century BC to the 6th century AD [SUPPORTED: https://en.wikipedia.org/wiki/Huckhoe_Settlement]; The settlement was once ringed by three oak palisades [SUPPORTED: https://en.wikipedia.org/wiki/Huckhoe_Settlement]"}]'::jsonb),
    ('9c1414b7-dda6-4bbc-ad6f-541dd811763d'::uuid, 'card_description', 'Inca buildings cut into a granite cliff at 3,436 m altitude, used for both administration and religious ceremonies. The stonework hugs the rock face.', 'Amid grass-grown Inca terraces, Qollmay keeps a walled-off natural cavern with Inca-style stonework inside. Beside it, a rock like a birth canal, perhaps a place of fertility rituals.', 'teaser-card-s014:9c1414b7-dda6-4bbc-ad6f-541dd811763d:card_description', 'teaser-card-s014 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '41d3df411b0040ce8480861c16f4973ba557e37faa39585d6dcd5263ed84d5dd|e8b8515e50d17a1a85f02824571b7883146b5816b272119eb1c6e6dc8846b7a4|e8b8515e50d17a1a85f02824571b7883146b5816b272119eb1c6e6dc8846b7a4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Amid grass-grown Inca terraces, Qollmay keeps a walled-off natural cavern with Inca-style stonework inside. Beside it, a rock like a birth canal, perhaps a place of fertility rituals."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Inca terraces surround the site (the site is embedded within them) [S5]; the terraces are overgrown with grass [S5]; the terraces are Inca-made [S5]; Qollmay has a walled-off natural cavern [S2]; the cavern has Inca-style stonework inside [S2]; beside (adjacent to) the cavern is a rock formation resembling a birth canal [S4]; the rock formation is perhaps (speculated to be) a place of fertility rituals [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Qollmay is an Inca archaeological site in Peru (Cusco Region, Anta Province, Chinchaypujio District) [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; The site lies in Peru (Cusco Region, Anta Province, Chinchaypujio District) [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; The terraces around the site are Inca-made [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; The Inca terraces are now grass-grown (overgrown with grass) [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; Qollmay has a natural cavern [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; The cavern is walled off [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; The cavern has Inca-style stonework inside [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; Beside the cavern there is a rock formation like a birth canal [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]; The birth-canal rock is speculated (not established) to have been a place of fertility rituals [SUPPORTED: https://en.wikipedia.org/wiki/Qollmay]"}]'::jsonb),
    ('9cb8e16e-1f97-47da-b7f9-558216c9b543'::uuid, 'card_description', 'A 5th-century BC storage building on the Athenian Acropolis, known only from inscriptions. It held bronze offerings — its name literally means "bronze warehouse."', 'The Chalkotheke, whose name means bronze store, stood on the Athenian Acropolis. Its function is known only from 4th century BC inscriptions, one ordering all its objects listed on a stele.', 'teaser-card-s014:9cb8e16e-1f97-47da-b7f9-558216c9b543:card_description', 'teaser-card-s014 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '2fa26f2e19a99f9d52aebcbc45f7e82a6ad754d3bc9ed854da094132ce8d1ef9|321a650f35f0a4612f419f948846628856836393f36e4b14170def4d26740bd0|321a650f35f0a4612f419f948846628856836393f36e4b14170def4d26740bd0', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Chalkotheke, whose name means bronze store, stood on the Athenian Acropolis. Its function is known only from 4th century BC inscriptions, one ordering all its objects listed on a stele."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Chalkotheke''s name means bronze store [S1]; it stood on the Athenian Acropolis [S1]; its function is known only from 4th century BC inscriptions [S2]; one of these texts (a decree) orders all the objects stored in it to be listed [S2, S3]; the list was to be inscribed on a stele [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Chalkotheke was a structure (a store) on the Athenian Acropolis, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Chalkotheke]; The name Chalkotheke means bronze store [SUPPORTED: https://en.wikipedia.org/wiki/Chalkotheke]; Its function is known only from inscriptions (nothing survives that shows it otherwise) [SUPPORTED: https://en.wikipedia.org/wiki/Chalkotheke]; The inscriptions that tell its function date to the 4th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Chalkotheke]; One inscription (a decree) orders all objects stored in the Chalkotheke to be listed [SUPPORTED: https://en.wikipedia.org/wiki/Chalkotheke]; The list is to be inscribed on a stele erected in front of the building [SUPPORTED: https://en.wikipedia.org/wiki/Chalkotheke]"}]'::jsonb),
    ('9d1f90a0-7c45-4903-a83c-7503daf3db1b'::uuid, 'card_description', 'Doric peripteral temple to Hephaestus, standing largely intact since 415 BC on the Agoraios Kolonos. It survived by serving as the Orthodox church of Saint George Akamates for over 1,200 years.', 'Above the Agora of Athens, the Temple of Hephaestus stands largely intact. Building began in 449 BC; of its 68 outer metopes only 18 were sculpted, ten showing the Labors of Heracles.', 'teaser-card-s014:9d1f90a0-7c45-4903-a83c-7503daf3db1b:card_description', 'teaser-card-s014 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'a73dbb1a0b56ebc00ee40dd475888e61bb9e3f5805a8c6c37614c37b106fb1e1|1e0d5469f3f77162f49a8e5f2d86306ecece147110dea4d6cbac591d61ffa8fe|1e0d5469f3f77162f49a8e5f2d86306ecece147110dea4d6cbac591d61ffa8fe', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Above the Agora of Athens, the Temple of Hephaestus stands largely intact. Building began in 449 BC; of its 68 outer metopes only 18 were sculpted, ten showing the Labors of Heracles."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the temple lies at the Agora of Athens, on top of a hill (above the Agora) [S2]; the temple stands largely intact [S1]; construction began in 449 BC [S4]; the temple has 68 outer (external) metopes [S6]; only 18 of the metopes were sculpted [S6]; ten of the sculpted metopes show the Labors of Heracles [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Temple of Hephaestus is a Greek temple above the Agora of Athens (north-west side of the Agora, on the Agoraios Kolonos hill) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]; The Temple of Hephaestus is a well-preserved Greek temple dedicated to Hephaestus [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]; The temple stands largely intact [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]; Building began in 449 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]; The temple has 68 outer (external) metopes [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]; Only 18 of the outer metopes were sculpted [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]; Ten of the sculpted metopes show the Labors of Heracles [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Hephaestus]"}]'::jsonb),
    ('9d230dae-1f9b-4d16-a2a0-cce28ff32c56'::uuid, 'card_description', 'Bronze Age burial mounds from the Cetina culture, named after the river valley. The Cetina people spread their burial customs across the Adriatic.', 'Mound fields line the valley slopes around Cetina, on a principal trade route from coast to hinterland, where the Cetina culture became dominant in the Early Bronze Age.', 'teaser-card-s014:9d230dae-1f9b-4d16-a2a0-cce28ff32c56:card_description', 'teaser-card-s014 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '78d4137dcf29a6093b9fe2368ba070fdc1a37bdc17112341952bf2fce4e0a67e|36224027dbbfa2ad680ff7ad90178f8fc48b14edfa48caf5edf047aa7d5d828f|36224027dbbfa2ad680ff7ad90178f8fc48b14edfa48caf5edf047aa7d5d828f', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Mound fields line the valley slopes around Cetina, on a principal trade route from coast to hinterland, where the Cetina culture became dominant in the Early Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "extensive mound fields are recorded on the valley slopes around Cetina [S4]; the place lies on a principal trade route between the coast and the hinterland [S1]; the Cetina culture became dominant in the Early Bronze Age [S3]; this dominance was in the Cetina valley area (the card''s ''where'') [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Cetina is a locality in Croatia (Cetina valley, Dalmatia) with prehistoric mound fields around it [SUPPORTED: https://en.wikipedia.org/wiki/Cetina]; The mound fields line the valley slopes [SUPPORTED: https://en.wikipedia.org/wiki/Cetina]; The Cetina valley lies on a principal trade route [SUPPORTED: https://en.wikipedia.org/wiki/Cetina]; The trade route runs from the coast to the hinterland [SUPPORTED: https://en.wikipedia.org/wiki/Cetina]; The Cetina culture became dominant here [SUPPORTED: https://en.wikipedia.org/wiki/Cetina]; The Cetina culture became dominant in the Early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Cetina]"}]'::jsonb),
    ('9d3a0f75-ce6d-4778-891e-e3fc60310f76'::uuid, 'card_description', 'A museum built directly over the ruins of Roman and Byzantine Athens. Glass floors let visitors look down at the ancient streets beneath their feet.', 'On the ancient road up to the sacred rock, the Acropolis Museum lies over ruins of Roman and early Byzantine Athens, showing more than 4,250 objects found on the rock and its slopes.', 'teaser-card-s014:9d3a0f75-ce6d-4778-891e-e3fc60310f76:card_description', 'teaser-card-s014 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '88368a997997e330d3ae45882ea54d1a236f47c706dde3dd9d9cb98f5c21dac5|5f4146d2b039401bfb0f7edfc8e807a8b26f6b2851ffcb084e6a1e192db689af|5f4146d2b039401bfb0f7edfc8e807a8b26f6b2851ffcb084e6a1e192db689af', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the ancient road up to the sacred rock, the Acropolis Museum lies over ruins of Roman and early Byzantine Athens, showing more than 4,250 objects found on the rock and its slopes."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the museum lies on the ancient road up to the sacred rock [S7]; the museum lies over ruins of Roman and early Byzantine Athens [S3]; more than 4,250 objects are shown in the museum [S6]; the objects shown were found on the rock and its slopes [S1, S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Acropolis Museum is an archaeological museum of the finds of the Acropolis of Athens, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_Museum]; The museum stands on the ancient road up to the sacred rock [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_Museum]; The museum lies over ruins of Roman and early Byzantine Athens [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_Museum]; More than 4,250 objects are shown in the museum [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_Museum]; The objects shown were found on the Acropolis rock and its slopes [SUPPORTED: https://en.wikipedia.org/wiki/Acropolis_Museum]"}]'::jsonb),
    ('9d58f665-8cc3-4438-9dc5-99885deb90d0'::uuid, 'card_description', 'The artificial ring structures made of broken stalagmites now have been dated by uranium series dating as 176.5 thousand years old.', 'Deep in Bruniquel Cave, 336 metres from the entrance, lie rings of broken stalagmites dated as 176.5 thousand years old, with traces of fire. Researchers say early Neanderthals built them.', 'teaser-card-s014:9d58f665-8cc3-4438-9dc5-99885deb90d0:card_description', 'teaser-card-s014 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '9d2b64ae72db65c0f0b3d0c0a19e75fd969a3133762e9cc2a1c8c4037686498d|bf9dd4c6534f6041273e08607c246c8e88eef508bd0798ba58cf01aa3554c809|bf9dd4c6534f6041273e08607c246c8e88eef508bd0798ba58cf01aa3554c809', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Deep in Bruniquel Cave, 336 metres from the entrance, lie rings of broken stalagmites dated as 176.5 thousand years old, with traces of fire. Researchers say early Neanderthals built them."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the structures lie 336 metres from the cave entrance (deep in the cave) [S2]; the structures are rings of broken stalagmites [S2, S6]; the rings are dated as 176.5 thousand years old [S6]; traces of fire were found [S3]; researchers say early Neanderthals built the structures [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Bruniquel Cave is a cave and archaeological site in southwestern France (near Bruniquel, east of Montauban) [SUPPORTED: https://en.wikipedia.org/wiki/Bruniquel_Cave]; Rings of broken stalagmites lie 336 metres from the cave entrance, deep inside the cave [SUPPORTED: https://en.wikipedia.org/wiki/Bruniquel_Cave]; The ring structures of broken stalagmites are dated as 176.5 thousand years old [SUPPORTED: https://en.wikipedia.org/wiki/Bruniquel_Cave]; The structures show traces of fire [SUPPORTED: https://en.wikipedia.org/wiki/Bruniquel_Cave]; Researchers say early Neanderthals built the stalagmite structures [SUPPORTED: https://en.wikipedia.org/wiki/Bruniquel_Cave]"}]'::jsonb),
    ('9e17ecc2-7c59-4f03-bea4-8d32de261d3e'::uuid, 'card_description', 'An early farming settlement from 6000 BC with layers from the Hassuna, Halaf, and Ubaid cultures. Three of Mesopotamia''s earliest civilizations are stacked in one tell.', 'In the Sinjar valley, the hills of Yarim Tepe hold an early farming settlement going back to about 6000 BC, its lower levels yielding as many as 21 pieces of worked copper or copper ore.', 'teaser-card-s014:9e17ecc2-7c59-4f03-bea4-8d32de261d3e:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '67e04c7f3f25cefb21be035c4d2290e0d61d14f9a623a130e26cfc0a7463c045|9c4d4a9d5caa6b97784677679d4652ba8425fd2eb47fe0e87ad3e84d9f1c1d10|9c4d4a9d5caa6b97784677679d4652ba8425fd2eb47fe0e87ad3e84d9f1c1d10', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In the Sinjar valley, the hills of Yarim Tepe hold an early farming settlement going back to about 6000 BC, its lower levels yielding as many as 21 pieces of worked copper or copper ore."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Yarim Tepe is in the Sinjar valley [S2]; the site consists of hills [S3]; it holds an early farming settlement [S1]; the settlement goes back to about 6000 BC [S1]; as many as 21 pieces of worked copper or copper ore were found in the lower levels [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Yarim Tepe is an archaeological site of an early farming settlement [SUPPORTED: https://en.wikipedia.org/wiki/Yarim_Tepe]; The settlement goes back to about 6000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Yarim_Tepe]; Yarim Tepe lies in the Sinjar valley (northern Iraq) [SUPPORTED: https://en.wikipedia.org/wiki/Yarim_Tepe]; The site consists of hills (several mounds) [SUPPORTED: https://en.wikipedia.org/wiki/Yarim_Tepe]; As many as 21 pieces of worked copper or copper ore were found in the lower levels of the settlement [SUPPORTED: https://en.wikipedia.org/wiki/Yarim_Tepe]"}]'::jsonb),
    ('9f3c5cb7-92a4-4ae6-b8c2-3235b723516f'::uuid, 'card_description', 'An Iron Age village built on a man-made island of timber and clay in 250 BC — the best-preserved prehistoric village ever found in Britain.', 'An Iron Age village on a man-made island in the Somerset Levels, Glastonbury Lake Village had round houses of hazel and willow under reeds. The peat kept wheel spokes and an unfinished hub.', 'teaser-card-s014:9f3c5cb7-92a4-4ae6-b8c2-3235b723516f:card_description', 'teaser-card-s014 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'dbabfc78d22482ccaebbddb375b10dfd2706c62e4d2a95708d5b47eed196c475|5bbaa46bb69062a1bee5ecc64c0d0ad4217cb83554d8410feb0cd4ce6992a689|5bbaa46bb69062a1bee5ecc64c0d0ad4217cb83554d8410feb0cd4ce6992a689', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "An Iron Age village on a man-made island in the Somerset Levels, Glastonbury Lake Village had round houses of hazel and willow under reeds. The peat kept wheel spokes and an unfinished hub."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "it was an Iron Age village [S1]; it stood on a man-made island (crannog) in the Somerset Levels [S1]; the village had round houses [S6]; the houses were made of hazel and willow covered with reeds [S6]; the peaty soil preserved wooden objects including wheel spokes [S7]; the peaty soil preserved an unfinished hub (nave) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Glastonbury Lake Village is a village in the Somerset Levels [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The village dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The village stood on a man-made island (crannog) [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The village had round houses [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The round houses were made of hazel and willow [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The houses were covered with reeds [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The peat preserved wheel spokes at the site [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]; The peat preserved an unfinished wheel hub (nave) at the site [SUPPORTED: https://en.wikipedia.org/wiki/Glastonbury_Lake_Village]"}]'::jsonb),
    ('a023ea22-2689-4ec1-9b56-6b6f7ed023b0'::uuid, 'card_description', 'The Dolmen of Pedra Branca is a burial tomb, used in the late Neolithic and, subsequently, in the late Chalcolithic periods.', 'High on a hill above the Vale de Figueira, the Dolmen of Pedra Branca held skeletons and many offerings, its chamber roof supported in the middle by a 2.2 meter tall quartzite pillar.', 'teaser-card-s014:a023ea22-2689-4ec1-9b56-6b6f7ed023b0:card_description', 'teaser-card-s014 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '1e4e5d8d7606c98e03f6fd48a22cf5e10f6360f51c607dc994b7005fd4de5fb7|26a3e70ddf105397e0ec5086acb412bdb2d934c408b845e229a748f85a61d2fa|26a3e70ddf105397e0ec5086acb412bdb2d934c408b845e229a748f85a61d2fa', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "High on a hill above the Vale de Figueira, the Dolmen of Pedra Branca held skeletons and many offerings, its chamber roof supported in the middle by a 2.2 meter tall quartzite pillar."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the dolmen lies high on a hill above (visually dominating) the Vale de Figueira [S7]; the dolmen held skeletons [S6]; many funerary offerings were found in it [S6]; the chamber roof was supported in the middle by a pillar [S3]; the pillar was 2.2 meters tall [S3]; the pillar was of quartzite [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Dolmen of Pedra Branca is a burial tomb (megalithic dolmen) [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Pedra_Branca]; The dolmen lies in the Vale de Figueira, in the parish of Melides (Grandola municipality, Setubal) [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Pedra_Branca]; The dolmen stands high on a hill above the Vale de Figueira [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Pedra_Branca]; The dolmen held skeletons [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Pedra_Branca]; The dolmen held many offerings [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Pedra_Branca]; The chamber roof was supported in the middle by a 2.2 meter tall quartzite pillar [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Pedra_Branca]"}]'::jsonb),
    ('a09044a9-4ff3-4df3-be04-72a953b67429'::uuid, 'card_description', 'Nine-terraced megalithic pyramid on the Cibedug River in West Java. Lebak Cibedug has menhirs and altars on each terrace, plus dolmens on site, a sacred complex in Banten regency''s highland forest.', 'On the slope of Pasir Manggu hill in west Java, Lebak Cibedug Temple climbs in nine terraces of oval andesite stones, set with menhirs and altars, a design older than the temples of Bali.', 'teaser-card-s014:a09044a9-4ff3-4df3-be04-72a953b67429:card_description', 'teaser-card-s014 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '1a6b3455d3df2bb167104fb5f5118ab686f9e9d0b0f5b2a74634dd9f8669f458|a3a2c183552c564a5ed00434915eff31eff6521b64a35041aa919e293f2e6b12|a3a2c183552c564a5ed00434915eff31eff6521b64a35041aa919e293f2e6b12', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the slope of Pasir Manggu hill in west Java, Lebak Cibedug Temple climbs in nine terraces of oval andesite stones, set with menhirs and altars, a design older than the temples of Bali."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the temple is on the slope of Pasir Manggu hill [S2]; it is in west Java (west end of the island of Java) [S1]; it has nine terraces [S3]; the terraces are built of oval andesite stones [S4]; the terraces are set with menhirs and altars [S3]; its design is older than the temples of Bali [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Lebak Cibedug is a terraced, pyramid-shaped sacred megalithic site (temple) in Banten Province at the west end of Java, Indonesia [SUPPORTED: https://en.wikipedia.org/wiki/Lebak_Cibedug]; The site is on the slope of Pasir Manggu hill [SUPPORTED: https://en.wikipedia.org/wiki/Lebak_Cibedug]; The structure climbs in nine terraces [SUPPORTED: https://banten.idntimes.com/travel/destination/lebak-cibedug-piramida-kuno-yang-tersembunyi-di-pedalaman-lebak-00-xwfcr-bqwf7q]; The terraces are built of oval-shaped andesite stones [SUPPORTED: https://en.wikipedia.org/wiki/Lebak_Cibedug]; The terraces are set with menhirs and altars [SUPPORTED: https://en.wikipedia.org/wiki/Lebak_Cibedug]; The design of Lebak Cibedug is older than the temples of Bali [SUPPORTED: https://en.wikipedia.org/wiki/Lebak_Cibedug]"}]'::jsonb),
    ('a0ad1eea-28f5-474e-bc9d-24e2d83cd4ca'::uuid, 'card_description', 'The stupa base is an elaborate construction, consisting of three tiers organised in a stair, and two sides.', 'From Hadda comes the Chakhil-i-Ghoundi Stupa, a small limestone stupa whose stepped base sets Hellenistic scenes on its bottom tier and Indian Buddhist scenes on the two above it.', 'teaser-card-s014:a0ad1eea-28f5-474e-bc9d-24e2d83cd4ca:card_description', 'teaser-card-s014 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'ae93105214675693afadb68e5b074514b59a5377d9822c8f0f69e2c4bf181b11|13c50bf456928c787ba19b3d43877c886c42428e79ec42b00300091b05c0bf59|13c50bf456928c787ba19b3d43877c886c42428e79ec42b00300091b05c0bf59', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "From Hadda comes the Chakhil-i-Ghoundi Stupa, a small limestone stupa whose stepped base sets Hellenistic scenes on its bottom tier and Indian Buddhist scenes on the two above it."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the stupa comes from Hadda [S1]; it is a small stupa [S1]; it is made of limestone [S1]; its base is stepped (three tiers organised in a stair) [S6]; Hellenistic scenes are on the bottom tier [S7]; Indian Buddhist scenes are on the top two tiers [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Chakhil-i-Ghoundi Stupa is a stupa from the Chakhil-i-Ghoundi monastery at the archaeological site of Hadda in eastern Afghanistan (the central claim: a stupa, from Hadda) [SUPPORTED: https://en.wikipedia.org/wiki/Chakhil-i-Ghoundi_Stupa]; The stupa is small [SUPPORTED: https://en.wikipedia.org/wiki/Chakhil-i-Ghoundi_Stupa]; The stupa is made of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Chakhil-i-Ghoundi_Stupa]; The stupa base is stepped (tiers organised in a stair) [SUPPORTED: https://en.wikipedia.org/wiki/Chakhil-i-Ghoundi_Stupa]; Hellenistic scenes are on the bottom tier of the base [SUPPORTED: https://en.wikipedia.org/wiki/Chakhil-i-Ghoundi_Stupa]; Indian Buddhist scenes are on the two tiers above the bottom tier [SUPPORTED: https://en.wikipedia.org/wiki/Chakhil-i-Ghoundi_Stupa]"}]'::jsonb),
    ('a25bcd91-5122-452f-9a4c-87377012c26c'::uuid, 'card_description', 'Castle Goff is considered to be a "round": these are small circular embanked enclosures, with one entrance; they date from the late Iron Age to the early post-Roman period.', 'On a ridge between tributaries of the River Allen, Castle Goff is considered a round: a circular embanked enclosure about 60 metres across, its rampart rising 3.5 metres above the ditch.', 'teaser-card-s014:a25bcd91-5122-452f-9a4c-87377012c26c:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '3acf267bb11df10ac51fb639e30b1569e59afbd2caefab782ea9a452249f022f|28b02f0f9eb827b3523f61be745aae298f2d44bd5f0dde995e1e1ddee5e02363|28b02f0f9eb827b3523f61be745aae298f2d44bd5f0dde995e1e1ddee5e02363', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a ridge between tributaries of the River Allen, Castle Goff is considered a round: a circular embanked enclosure about 60 metres across, its rampart rising 3.5 metres above the ditch."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castle Goff lies on a ridge between tributaries of the River Allen [S5]; Castle Goff is considered a round [S3]; a round is a circular embanked enclosure [S3]; the enclosure is about 60 metres across [S6]; the rampart rises 3.5 metres above the ditch [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Castle Goff is a ''round'', a small circular embanked enclosure (the central claim: an Iron Age to early post-Roman enclosure in Cornwall, England) [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Goff]; Castle Goff is an enclosure (scheduled monument) in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Goff]; It stands on a ridge between tributaries of the River Allen [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Goff]; The enclosure is about 60 metres across [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Goff]; The rampart rises 3.5 metres above the ditch [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Goff]"}]'::jsonb),
    ('a2d92ad7-ebd8-4445-9f48-a1458fd302fe'::uuid, 'card_description', 'Unfinished step pyramid at Zawyet El Aryan dated to around 2630 BC, 3rd Dynasty. Its owner is unconfirmed—attribution to pharaoh Khaba rests on a nearby stone vessel bearing his name.', 'At Zawyet El Aryan stands the Layer Pyramid, a ruined 3rd Dynasty step pyramid where excavators found no artefacts and no trace of a burial. Did it ever hold a pharaoh?', 'teaser-card-s014:a2d92ad7-ebd8-4445-9f48-a1458fd302fe:card_description', 'teaser-card-s014 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', 'e40848d1e0455ea5d5b1eceede4092beb7d39c964b339b600fc66183eeb4dc7e|fb3fc6916f8d3b5317b4c4dd79e7c4bde95efd76e0e079a327535592199ca152|fb3fc6916f8d3b5317b4c4dd79e7c4bde95efd76e0e079a327535592199ca152', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "At Zawyet El Aryan stands the Layer Pyramid, a ruined 3rd Dynasty step pyramid where excavators found no artefacts and no trace of a burial. Did it ever hold a pharaoh?"}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Layer Pyramid is at Zawyet El Aryan [S1]; it is a ruined step pyramid [S1]; it dates to the 3rd Dynasty [S1]; excavators found no artefacts [S4]; excavators found no trace of a burial [S4]; it is unclear whether the pyramid ever held (was used to bury) a pharaoh (implied by the question) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Layer Pyramid is a ruined step pyramid (the central claim: a pyramid) at the necropolis of Zawyet El Aryan [SUPPORTED: https://en.wikipedia.org/wiki/Layer_Pyramid]; It stands at Zawyet El Aryan [SUPPORTED: https://en.wikipedia.org/wiki/Layer_Pyramid]; It dates to the 3rd Dynasty [SUPPORTED: https://en.wikipedia.org/wiki/Layer_Pyramid]; Excavators found no artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Layer_Pyramid]; Excavators found no trace of a burial [SUPPORTED: https://en.wikipedia.org/wiki/Layer_Pyramid]; It is uncertain whether the pyramid ever held a pharaoh [SUPPORTED: https://en.wikipedia.org/wiki/Layer_Pyramid]"}]'::jsonb),
    ('a36951c3-c172-4782-8fa0-a0cfd2e7650c'::uuid, 'card_description', 'A 1st-century AD Roman villa with an exceptional mosaic floor — the primary surviving treasure from one of the province''s most significant estates.', 'In orchards near Calanda lay the Roman Villa of Camino de Albalate, found in January 1964. Now dismantled, it gave up a polychrome mosaic of varied themes, rescued from its floor.', 'teaser-card-s014:a36951c3-c172-4782-8fa0-a0cfd2e7650c:card_description', 'teaser-card-s014 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '73013920d80055b002ff6d70b2ec89e66cb65a2ebc02428999989ba1bb85eceb|2a37cab451448ef21426f9ea840b6e937528120ee7de747fb7bf2cd0e1c12232|2a37cab451448ef21426f9ea840b6e937528120ee7de747fb7bf2cd0e1c12232', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "In orchards near Calanda lay the Roman Villa of Camino de Albalate, found in January 1964. Now dismantled, it gave up a polychrome mosaic of varied themes, rescued from its floor."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the villa is a Roman site near Calanda [S1]; it lay in the orchard area [S2]; it was found (discovered) in January 1964 [S3]; the site is now dismantled [S2]; it yielded a polychrome mosaic [S4, S5]; the mosaic has varied themes [S5]; the mosaic was rescued from the villa''s floor [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Roman Villa of Camino de Albalate is a Roman site (a villa) near Calanda, Teruel, Spain (the central claim: a Roman villa near Calanda) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]; A large Roman villa once stood at the site [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]; The site lay in orchards [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]; The site was found in January 1964 [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]; The site is now dismantled [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]; It gave up a polychrome mosaic of varied themes [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]; The mosaic was rescued from the villa''s floor [SUPPORTED: https://en.wikipedia.org/wiki/Roman_villa_of_Camino_de_Albalate]"}]'::jsonb),
    ('a72bf9fc-f2ef-4f84-b322-f9707dac50f5'::uuid, 'card_description', 'A ruined megalithic temple with a typical two-apse plan and paved court. Coastal erosion was believed to have destroyed it, but 2015 investigations found the remains intact.', 'Built between 3600 and 3000 BC and thought largely lost to coastal erosion, Xrobb l-Għaġin Temple survives, as 2015 investigations revealed, with an unrecorded megalithic structure nearby.', 'teaser-card-s014:a72bf9fc-f2ef-4f84-b322-f9707dac50f5:card_description', 'teaser-card-s014 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8b56ff98f4380fdcfd8f034f686610d170a6210662997c4beab9bb7619b49bba|d056fade57b1f3ef3c8277356531fbf19a149ac74ae6547e80e8e3762a0f19db|d056fade57b1f3ef3c8277356531fbf19a149ac74ae6547e80e8e3762a0f19db', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Built between 3600 and 3000 BC and thought largely lost to coastal erosion, Xrobb l-Għaġin Temple survives, as 2015 investigations revealed, with an unrecorded megalithic structure nearby."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the temple was built between 3600 and 3000 BC [S5]; it was thought (believed) to be largely lost (destroyed) to coastal erosion [S3]; it survives, as 2015 investigations revealed [S3]; a previously unrecorded megalithic structure lies nearby [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Xrobb l-Għaġin Temple is a ruined megalithic temple at Xrobb l-Għaġin, Marsaxlokk, Malta (the central claim: a megalithic temple in Malta) [SUPPORTED: https://en.wikipedia.org/wiki/Xrobb_l-G%C4%A7a%C4%A1in_Temple]; The temple was built between 3600 and 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Xrobb_l-G%C4%A7a%C4%A1in_Temple]; It was thought to have been largely lost to coastal erosion [SUPPORTED: https://en.wikipedia.org/wiki/Xrobb_l-G%C4%A7a%C4%A1in_Temple]; Investigations in 2015 revealed that the temple remains still survive [SUPPORTED: https://en.wikipedia.org/wiki/Xrobb_l-G%C4%A7a%C4%A1in_Temple]; An unrecorded megalithic structure lies nearby [SUPPORTED: https://en.wikipedia.org/wiki/Xrobb_l-G%C4%A7a%C4%A1in_Temple]"}]'::jsonb),
    ('a744c90a-9a6a-4c23-ae16-ce84becaaa9a'::uuid, 'card_description', 'Huapalcalco flourished during the Mesoamerican Classic period and was associated with the state of Teotihuacan.', 'On the western slope of Tecolote hill stands the Huapalcalco Pyramid, three-sided and influenced by Teotihuacan, its altar perhaps once used for sacrificial offerings.', 'teaser-card-s014:a744c90a-9a6a-4c23-ae16-ce84becaaa9a:card_description', 'teaser-card-s014 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '0f4734690beb7b576580efc2006d286dcc47c4401e3f465e217e5e4bbe4d621d|bfd01d05319743fef6cc843b24df1f9950d15bdc8a25ebf5971b0be170166697|bfd01d05319743fef6cc843b24df1f9950d15bdc8a25ebf5971b0be170166697', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On the western slope of Tecolote hill stands the Huapalcalco Pyramid, three-sided and influenced by Teotihuacan, its altar perhaps once used for sacrificial offerings."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Huapalcalco Pyramid stands on the western slope of the hill Tecolote [S2, S7]; the pyramid is three-sided [S7]; the pyramid is influenced by Teotihuacan [S7]; the pyramid has an altar [S7]; the altar may (perhaps) have been used for sacrificial offerings, a hedge [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Huapalcalco Pyramid is a pyramid, a monumental structure at the pre-Columbian archaeological site of Huapalcalco in Hidalgo, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Huapalcalco]; The pyramid stands on the western slope of Tecolote hill [SUPPORTED: https://en.wikipedia.org/wiki/Huapalcalco]; The pyramid is three-sided [SUPPORTED: https://www.mexicodesconocido.com.mx/huapalcalco-hidalgo.html]; The pyramid is influenced by Teotihuacan [SUPPORTED: https://www.mexicodesconocido.com.mx/huapalcalco-hidalgo.html]; Its altar may once have been used for sacrificial offerings [SUPPORTED: https://en.wikipedia.org/wiki/Huapalcalco]"}]'::jsonb),
    ('a7abbf5d-8bea-4e7f-9df8-bb82169889ab'::uuid, 'card_description', 'A Wari culture complex at 3,400 meters near Huaraz, dating to around 1100 AD. Its multi-story stone structures preserve the highland architecture of this pre-Inca civilization in the Ancash region.', 'Near the village of Paria, 6 km northeast of Huaraz in Ancash and 3,400 m up, stands Wilcahuaín, regarded as one of the most important archaeological sites of the Wari culture.', 'teaser-card-s014:a7abbf5d-8bea-4e7f-9df8-bb82169889ab:card_description', 'teaser-card-s014 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '20e5283ced17002e08be15955fdc2ba286e1a9b64e22775ff0c5e5af2115f258|d757d6e62d0a83dbc861c1d0658a63b251c0ecc55077877391d5b2e3d343a31c|d757d6e62d0a83dbc861c1d0658a63b251c0ecc55077877391d5b2e3d343a31c', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Near the village of Paria, 6 km northeast of Huaraz in Ancash and 3,400 m up, stands Wilcahuaín, regarded as one of the most important archaeological sites of the Wari culture."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is near the village of Paria [S2]; it is 6 km northeast of Huaraz [S2]; Huaraz is in Ancash [S2]; the site lies at 3,400 m elevation [S2]; it is regarded as one of the most important archaeological sites of the Wari culture [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Wilcahuaín is an archaeological site in Peru (central claim: an archaeological site) [SUPPORTED: https://en.wikipedia.org/wiki/Wilcahua%C3%ADn]; It is near the village of Paria [SUPPORTED: https://en.wikipedia.org/wiki/Wilcahua%C3%ADn]; It lies 6 km northeast of Huaraz [SUPPORTED: https://en.wikipedia.org/wiki/Wilcahua%C3%ADn]; It is in Ancash [SUPPORTED: https://en.wikipedia.org/wiki/Wilcahua%C3%ADn]; It stands at an elevation of 3,400 m [SUPPORTED: https://en.wikipedia.org/wiki/Wilcahua%C3%ADn]; It is regarded as one of the most important archaeological sites of the Wari culture [SUPPORTED: https://en.wikipedia.org/wiki/Wilcahua%C3%ADn]"}]'::jsonb),
    ('a98dcb51-39c4-4ab9-b34e-1f10a9aa14d9'::uuid, 'card_description', 'An ancient trackway dated to 600-450 BC but likely used since the Stone Age. Later generations called it the pilgrims'' route from Winchester to Canterbury.', 'The Pilgrims'' Way, supposedly taken by pilgrims from Winchester to Thomas Becket''s shrine at Canterbury, is a comparatively recent name for an ancient trackway dated by finds to 600–450 BC.', 'teaser-card-s014:a98dcb51-39c4-4ab9-b34e-1f10a9aa14d9:card_description', 'teaser-card-s014 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '8ae41578d1ffba67627943991d373f1040e9cd2d000bff30314ebf0e967b5dfa|2e0c03928deb10e70666140b81cea6933dd9705ee6e730d3ad1079d792a86b35|2e0c03928deb10e70666140b81cea6933dd9705ee6e730d3ad1079d792a86b35', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Pilgrims'' Way, supposedly taken by pilgrims from Winchester to Thomas Becket''s shrine at Canterbury, is a comparatively recent name for an ancient trackway dated by finds to 600–450 BC."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the Pilgrims'' Way is the route supposedly taken by pilgrims (hedged) [S1]; the route ran from Winchester to Thomas Becket''s shrine at Canterbury [S1]; the name Pilgrims'' Way is of comparatively recent coinage [S2]; the name is applied to an ancient trackway [S2]; the trackway is dated by archaeological finds to 600-450 BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Pilgrims'' Way is a trackway (a historic route) in England, running along the North Downs [SUPPORTED: https://en.wikipedia.org/wiki/Pilgrims%27_Way]; The Pilgrims'' Way was supposedly (not demonstrably) taken by pilgrims [SUPPORTED: https://en.wikipedia.org/wiki/Pilgrims%27_Way]; The route ran from Winchester to Thomas Becket''s shrine at Canterbury [SUPPORTED: https://en.wikipedia.org/wiki/Pilgrims%27_Way]; The name Pilgrims'' Way is comparatively recent [SUPPORTED: https://en.wikipedia.org/wiki/Pilgrims%27_Way]; The Pilgrims'' Way name is applied to a pre-existing ancient trackway [SUPPORTED: https://en.wikipedia.org/wiki/Pilgrims%27_Way]; The ancient trackway is dated by finds to 600–450 BC [SUPPORTED: https://en.wikipedia.org/wiki/Pilgrims%27_Way]"}]'::jsonb),
    ('ab0a09e4-2350-42b5-b864-6a9330e4670f'::uuid, 'card_description', 'A double-ringed Bronze Age stone circle from 1700-1400 BC. The outer ring has 15 stones, the inner has 10 -- none taller than 60 centimetres.', 'The Birkrigg Stone Circle sets 12 stones inside a ring of 20 on Birkrigg Common. Beneath its cobbled pavements lay five cremations, one covered by an inverted urn.', 'teaser-card-s014:ab0a09e4-2350-42b5-b864-6a9330e4670f:card_description', 'teaser-card-s014 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', 'ec28b59d05185b6c876730e28283e7306518d14c7f20cb0466d07a73aad74c77|9c1a882d7b6060c66a6e566c061d2d17edc781cfb923d3fbb468e270e42e42ad|9c1a882d7b6060c66a6e566c061d2d17edc781cfb923d3fbb468e270e42e42ad', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Birkrigg Stone Circle sets 12 stones inside a ring of 20 on Birkrigg Common. Beneath its cobbled pavements lay five cremations, one covered by an inverted urn."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the circle has an inner ring of 12 stones [S2]; the inner ring sits inside an outer ring of 20 stones [S2]; the circle is on Birkrigg Common [S1]; the inner circle has cobbled pavements (an upper and a lower layer of cobbles) [S3]; five cremations lay beneath the pavements [S4]; one of the cremations was covered by an inverted urn [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Birkrigg Stone Circle is a Bronze Age stone circle on Birkrigg Common [SUPPORTED: https://en.wikipedia.org/wiki/Birkrigg_stone_circle]; The circle has an inner ring of 12 stones [SUPPORTED: https://co-curate.ncl.ac.uk/resources/view/108728/]; The inner ring of 12 stones is set inside an outer ring of 20 stones [SUPPORTED: https://co-curate.ncl.ac.uk/resources/view/108728/]; Beneath the circle lay cobbled pavements (an upper and a lower pavement of cobbles) [SUPPORTED: https://co-curate.ncl.ac.uk/resources/view/108728/]; Beneath the cobbled pavements lay five cremations [SUPPORTED: https://en.wikipedia.org/wiki/Birkrigg_stone_circle]; One of the five cremations was covered by an inverted urn [SUPPORTED: https://en.wikipedia.org/wiki/Birkrigg_stone_circle]"}]'::jsonb),
    ('abe8f81a-dcdb-42b8-9f99-a763c858fd7f'::uuid, 'card_description', 'A cairn at Ljungarums parish near Jönköping, dated c. 1700–500 BC — originally encircled by up to 100 sandstone slabs. Four smaller graves were added at its foot some 1,500 years later.', 'Just south of Jönköping, the Bronze Age barrow of Sagaholm was ringed by sandstone slabs, probably as many as 100. Of the slabs that remain, 15 are carved with ships, animals and people.', 'teaser-card-s014:abe8f81a-dcdb-42b8-9f99-a763c858fd7f:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'b304cce562f19c5ca7fa443b503e9b795c70a66e863fc0becf2962f37919f5d4|f6d410bc10b9231177fc685cd368b3d4625538c374b4f8b8ebf0456c60b5dec6|f6d410bc10b9231177fc685cd368b3d4625538c374b4f8b8ebf0456c60b5dec6', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Just south of Jönköping, the Bronze Age barrow of Sagaholm was ringed by sandstone slabs, probably as many as 100. Of the slabs that remain, 15 are carved with ships, animals and people."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sagaholm is just south of Jönköping [S2]; it is a Bronze Age barrow [S1, S3, S4]; the barrow was ringed by sandstone slabs [S4]; the ring probably numbered as many as 100 slabs [S4]; 15 of the remaining slabs are carved [W1, W2]; the carvings show ships, animals and people [S5, W1, W2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Sagaholm is a Bronze Age barrow / burial mound (central claim: a burial mound) [SUPPORTED: https://en.wikipedia.org/wiki/Sagaholm]; Sagaholm lies just south of Jönköping [SUPPORTED: https://en.wikipedia.org/wiki/Sagaholm]; The barrow was ringed by sandstone slabs [SUPPORTED: https://en.wikipedia.org/wiki/Sagaholm]; The ring probably numbered as many as 100 slabs [SUPPORTED: https://digitaltmuseum.se/021028572540/hall]; Of the slabs that remain, 15 are carved [SUPPORTED: https://digitaltmuseum.se/021028572540/hall]; The carvings show ships, animals and people [SUPPORTED: https://digitaltmuseum.se/021028572540/hall]"}, {"source": "web fact W1", "url": "https://jonkopingslansmuseum.se/se-och-gora/kalender/lendar_category%25/sagaholmshogen/", "quote": "Av de 46 hällarna som fanns kvar i kantkedjan var 15 ristade med skepp, hästar, hjortdjur och människofigurer."}, {"source": "web fact W2", "url": "https://sv.wikipedia.org/wiki/Sagaholmsh%C3%B6gen", "quote": "Av de 45 återstående hällarna i kantkedjan var 15 ristade med skepp, hästar, hjortdjur och människofigurer."}]'::jsonb),
    ('acec1746-35a0-4d0e-be03-1d240bad074c'::uuid, 'card_description', '600-909 AD Maya settlement in Petén with three groups of platforms on a north-south axis. Group A''s pyramid stands over 10 m tall in a wooded hilltop — largely unexcavated.', 'On a wooded hilltop in Petén, a Maya pyramid over 10 metres high rises among the collapsed structures of El Temblor, and a damaged stela still stands to its east.', 'teaser-card-s014:acec1746-35a0-4d0e-be03-1d240bad074c:card_description', 'teaser-card-s014 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', '659989f7f9e9cc42cf22abc71838bca2529878faed97c3075ab4b215228f2a87|9ea52bb03a34718472640ffa64c66bcff5ec263af79fd493a27a5119af0f1104|9ea52bb03a34718472640ffa64c66bcff5ec263af79fd493a27a5119af0f1104', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a wooded hilltop in Petén, a Maya pyramid over 10 metres high rises among the collapsed structures of El Temblor, and a damaged stela still stands to its east."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the pyramid is on a wooded hilltop [S5]; the site is in Petén [S1]; the site is Maya [S1]; the pyramid is over 10 metres high [S5]; the pyramid rises among collapsed structures [S4, S5]; a damaged stela stands east of the pyramid [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "El Temblor is a Maya archaeological site, once the location of a Maya settlement [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; El Temblor is in the Petén region of Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; The pyramid stands on a wooded hilltop [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; The site has a pyramid over 10 metres high [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; The pyramid is a Maya pyramid, part of the ruins of the Maya settlement [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; The pyramid rises among collapsed structures [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; A stela at the site is damaged [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]; The stela still stands to the east of the pyramid [SUPPORTED: https://en.wikipedia.org/wiki/El_Temblor]"}]'::jsonb),
    ('ad191503-1e6b-405c-bd52-fca93895617e'::uuid, 'card_description', 'Three aligned hypogea dug side by side, originally separate but later joined by passages. Each has a unique plan, but all share interconnecting galleries.', 'Three hypogea dug side by side in Mqabba, joined by narrow passages: the Tal-Mintna Catacombs keep an altar flanked by pillars carved in relief, yet no clear Christian iconography.', 'teaser-card-s014:ad191503-1e6b-405c-bd52-fca93895617e:card_description', 'teaser-card-s014 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '4cd94a315ea88f4fe362f88a844d912fb44aa45d145240f94c933b0273c6759b|a43f8c172b3dce63a290f322bb4ba1dcd7b07dcad1de0e8e0dad43144fb46af9|a43f8c172b3dce63a290f322bb4ba1dcd7b07dcad1de0e8e0dad43144fb46af9', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Three hypogea dug side by side in Mqabba, joined by narrow passages: the Tal-Mintna Catacombs keep an altar flanked by pillars carved in relief, yet no clear Christian iconography."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site has three hypogea [S1, S2]; they were dug side by side [S2]; they are in Mqabba [S1]; they are joined by narrow passages [S2]; one hypogeum has an altar flanked by pillars carved in relief [S3]; no clear Christian iconography survives in any of the hypogea [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Tal-Mintna Catacombs are a hypogea (underground burial) complex [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; The catacombs are in Mqabba, Malta [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; The site consists of three hypogea [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; The three hypogea were dug side by side [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; The three hypogea are joined by narrow passages [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; The catacombs keep an altar [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; The altar is flanked by pillars carved in relief [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]; No clear Christian iconography survives in the hypogea [SUPPORTED: https://en.wikipedia.org/wiki/Tal-Mintna_Catacombs]"}]'::jsonb),
    ('ad1ee295-b7b8-47bf-a8d6-8a14ce362d32'::uuid, 'card_description', 'The site was cataloged during an archaeological survey carried out in 1967–1968 by Shmarya Guttman and Claire Epstein.', 'More than 42,000 basalt rocks ring a central mound in concentric circles: Rujum Al-Hiri, the Wheel of Giants, on a Golan plateau covered with hundreds of dolmens.', 'teaser-card-s014:ad1ee295-b7b8-47bf-a8d6-8a14ce362d32:card_description', 'teaser-card-s014 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', 'e60df35ffce515d9a9d68faee1d6ffa07eea5c59bfcb58a12f76177220aa1618|c62c63cf9327d76ade4fdc72064e21a554bfb6ef917586cd4a073dbcf40186ec|c62c63cf9327d76ade4fdc72064e21a554bfb6ef917586cd4a073dbcf40186ec', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "More than 42,000 basalt rocks ring a central mound in concentric circles: Rujum Al-Hiri, the Wheel of Giants, on a Golan plateau covered with hundreds of dolmens."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "more than 42,000 basalt rocks make up the structure [S3]; the rocks are arranged in concentric circles [S1, S3]; the circles surround a central mound [S1, S3]; the site is also called the Wheel of Giants [S1]; it lies on a plateau in the Golan [S2]; the plateau is covered with hundreds of dolmens [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Rujm al-Hiri is an ancient megalithic structure of concentric stone circles [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; A central mound (tumulus) sits at the center of the rings [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; It is made up of more than 42,000 rocks [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; The rocks are basalt [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; The rocks are arranged in concentric circles [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; Rujm al-Hiri is known as the Wheel of Giants [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; It is located in the Golan [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]; It stands on a plateau covered with hundreds of dolmens [SUPPORTED: https://en.wikipedia.org/wiki/Rujm_el-Hiri]"}]'::jsonb),
    ('ad4967fa-1303-4b2c-822e-de70130f841b'::uuid, 'card_description', 'In 1877, William Greenwell and Llewellynn Jewitt excavated at the site, and in the late 1930s the Derbyshire Archaeological Society set two of the orthostats standing again.', 'On Harthill Moor stand the Grey Ladies of Nine Stones Close, a stone circle whose purpose is unknown. Its ring had seven stones in the mid-19th century; four remain.', 'teaser-card-s014:ad4967fa-1303-4b2c-822e-de70130f841b:card_description', 'teaser-card-s014 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', '0dbe51e2757bdc627a974f209bfe36932d27068f464b9dbfd00457b2732fd989|5277fa1702bf6e1a05a1dd6b037fb160e3258a96fa08242234fbff6f4fa49119|5277fa1702bf6e1a05a1dd6b037fb160e3258a96fa08242234fbff6f4fa49119', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On Harthill Moor stand the Grey Ladies of Nine Stones Close, a stone circle whose purpose is unknown. Its ring had seven stones in the mid-19th century; four remain."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the site is on Harthill Moor [S1]; it is also known as the Grey Ladies [S1]; it is a stone circle [S1]; the purpose of the monument is unknown (statement of the unknown) [S2]; the ring had seven stones in the mid-19th century [S4]; four stones remain [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Nine Stones Close is a stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; Nine Stones Close is on Harthill Moor [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; Nine Stones Close is also known as the Grey Ladies [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; The purpose of the stone circle is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; The ring had seven stones in the mid-19th century [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; Seven stones were recorded as part of the circle as of 1847 (mid-19th century) [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; Four stones of the ring remain [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]; Only four stones remain standing in the ring today [SUPPORTED: https://en.wikipedia.org/wiki/Nine_Stones_Close]"}]'::jsonb),
    ('adaf3933-e799-422f-92a4-29462e57df50'::uuid, 'card_description', 'Built from around 150 granite orthostats in the Valdecañas reservoir near Peraleda de la Mata, this megalithic circle sits underwater most of the year — only emerging during severe droughts.', 'Called the Spanish Stonehenge, the Dolmen of Guadalperal lies within the Valdecañas reservoir on the Tagus, a megalithic monument from around 3000 BC, visible only when the water allows.', 'teaser-card-s014:adaf3933-e799-422f-92a4-29462e57df50:card_description', 'teaser-card-s014 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '3310ac421ac27945723d316f463a29848de34747d20c5befbb7b5a06a66a4a9e|58d38da26bf24a722c274239a0a557ba4c3c6ed4826c4eeaf52eeb48e43f5a53|58d38da26bf24a722c274239a0a557ba4c3c6ed4826c4eeaf52eeb48e43f5a53', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Called the Spanish Stonehenge, the Dolmen of Guadalperal lies within the Valdecañas reservoir on the Tagus, a megalithic monument from around 3000 BC, visible only when the water allows."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the dolmen is called the Spanish Stonehenge [S1]; it lies within the Valdecañas reservoir [S3]; the reservoir is on the Tagus [S3]; it is a megalithic monument [S1]; it dates from around 3000 BC [S1]; it is visible only when the water level allows [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Dolmen of Guadalperal is a megalithic monument [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]; It is called the Spanish Stonehenge [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]; The monument dates from around 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]; It lies within the Valdecañas reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]; The reservoir is on the Tagus river [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]; It is visible only when the water level allows [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]; The reservoir flooded the monument, so it can be seen only when water levels are low [SUPPORTED: https://en.wikipedia.org/wiki/Dolmen_of_Guadalperal]"}]'::jsonb),
    ('adb88f40-6164-475b-972f-5d85128e1ff2'::uuid, 'card_description', 'Established around 122 AD under Hadrian, this coastal fort north of Maryport produced the largest assemblage of Roman military altar stones ever recovered from a single site.', 'On a hill north of the River Ellen, the Roman fort of Alauna served Hadrian''s Wall at its western extremity from around AD 122. No other site in Britain has yielded more altars.', 'teaser-card-s014:adb88f40-6164-475b-972f-5d85128e1ff2:card_description', 'teaser-card-s014 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'a263e15a3f253ee7341ed97b7ad673069befc637d168032ead1f6f409097f12e|cdb58ac88314712c7c7fd78dfab6b57fdca5b460821471a14d9c9e4b64cdbea7|cdb58ac88314712c7c7fd78dfab6b57fdca5b460821471a14d9c9e4b64cdbea7', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "On a hill north of the River Ellen, the Roman fort of Alauna served Hadrian''s Wall at its western extremity from around AD 122. No other site in Britain has yielded more altars."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Alauna was a Roman fort [S1]; the fort stands on a hill north of the River Ellen [S4]; it served Hadrian''s Wall at its western extremity [S5]; it dates from around AD 122 [S5]; no other site in Britain has yielded more altars [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Alauna, Maryport is a Roman fort (castrum) in Roman Britain, at Maryport [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]; The fort stands on a hill north of the River Ellen [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]; The fort served the defences of Hadrian''s Wall at its western extremity [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]; The fort was established around AD 122 [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]; No other site in Britain has yielded more altars than Alauna [SUPPORTED: https://en.wikipedia.org/wiki/Alauna_(Maryport)]"}]'::jsonb),
    ('ae4088f2-d0f0-472e-a783-459f246811c6'::uuid, 'card_description', '3rd-century AD Roman baths sealed beneath a motorway north of Welwyn Garden City. When the A1(M) was built, engineers constructed a steel vault around the ruins, preserving a near-complete hypocaust.', 'Under a motorway, a steel vault shelters the Welwyn Roman Baths: the hypocaust, tepidarium, caldarium and cold bath of a villa first built in the 3rd century AD.', 'teaser-card-s014:ae4088f2-d0f0-472e-a783-459f246811c6:card_description', 'teaser-card-s014 (teaser-card): teaser card, 161 characters, checked PASS, web-verified VERIFIED', '72b2e2e24f2631ab7884b500328dca9baad2071bae5b31c72f15d34881ae2d76|a7efefedee56c1345ccec815325bb6dc0f7cd050e152317763084f0ab3ac6f03|a7efefedee56c1345ccec815325bb6dc0f7cd050e152317763084f0ab3ac6f03', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Under a motorway, a steel vault shelters the Welwyn Roman Baths: the hypocaust, tepidarium, caldarium and cold bath of a villa first built in the 3rd century AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the baths lie under a motorway [S1, S5]; a steel vault shelters the baths [S6]; the visible remains include the hypocaust [S7]; the visible remains include the tepidarium and the caldarium [S7]; the visible remains include the cold bath [S7]; the baths belonged to a villa [S2]; the villa was first built in the 3rd century AD [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Welwyn Roman Baths are a Roman bath ruin at Welwyn (Hertfordshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The baths lie under a motorway [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; A steel vault shelters the baths [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The remains include a hypocaust [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The remains include a tepidarium [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The remains include a caldarium [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The remains include a cold bath [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The baths were part of a villa (the Dicket Mead villa) [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]; The villa was first built in the 3rd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Welwyn_Roman_Baths]"}]'::jsonb),
    ('ae5fec13-59e9-433e-8579-9d6d1110f0b6'::uuid, 'card_description', 'A Thracian city with a Temple of Asclepius on the hill of Hissarlaka. It received the name Ulpia Pautalia from Emperor Trajan and minted coins depicting its public buildings.', 'Its Thracian name means spring city, after the hot springs there: Pautalia, a great ancient city now in Kyustendil, is noted for its temple of Asclepius on the hill of Hissarlaka.', 'teaser-card-s014:ae5fec13-59e9-433e-8579-9d6d1110f0b6:card_description', 'teaser-card-s014 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '592c2011b39c254b027afc60485304608f5ec4f65aa0694de16054a49988dbee|dc1fdfd3f38139a9439c7e1ff05f0ce43037bb79359cdb63a8c7ce046d50750a|dc1fdfd3f38139a9439c7e1ff05f0ce43037bb79359cdb63a8c7ce046d50750a', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Its Thracian name means spring city, after the hot springs there: Pautalia, a great ancient city now in Kyustendil, is noted for its temple of Asclepius on the hill of Hissarlaka."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "the name Pautalia is Thracian [S4]; the name means spring city [S4]; the name refers to the hot springs there [S4]; Pautalia is a great ancient city [S1]; it is now in Kyustendil [S1]; it is noted for its temple of Asclepius [S3]; the temple is on the hill of Hissarlaka [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Pautalia is an ancient city (of Thrace) [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; Pautalia was a great ancient city [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; Pautalia is now located in Kyustendil (Bulgaria) [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; The name Pautalia is Thracian [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; The name means spring city [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; The name refers to the hot springs at the site [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; Pautalia is noted for a temple of Asclepius [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]; The temple of Asclepius stood on the hill of Hissarlaka [SUPPORTED: https://en.wikipedia.org/wiki/Pautalia]"}]'::jsonb),
    ('ae79d7fc-8820-4ca0-baf1-b162e08ecc86'::uuid, 'card_description', 'Doric tetrastyle temple in the Agora''s southwest, built under Augustus from spoliated Hellenistic blocks and material from a 5th-century BC stoa at Thorikos.', 'No one knows which god or hero the Southwest Temple of the Ancient Agora of Athens honoured. Built from older fragments in the age of Augustus, it was itself stripped after 267 AD.', 'teaser-card-s014:ae79d7fc-8820-4ca0-baf1-b162e08ecc86:card_description', 'teaser-card-s014 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'dc6b1914baa1c5cd5f2a80f6101cfff6fc8249e14b7e7a2b6c62eef3a4b96643|14239078a6917f736cd70229622a32fd1373264568fd9f68c0ff7b3227af71f4|14239078a6917f736cd70229622a32fd1373264568fd9f68c0ff7b3227af71f4', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "No one knows which god or hero the Southwest Temple of the Ancient Agora of Athens honoured. Built from older fragments in the age of Augustus, it was itself stripped after 267 AD."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "it is unknown which god or hero the temple was dedicated to (statement of the unknown) [S4]; the temple was built from older fragments [S3]; it was built in the age of Augustus [S3]; the temple itself was later stripped (spoliated) for building material [S5]; the stripping came after 267 AD, after the Herulian sack [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "The Southwest Temple is a temple in the southwest part of the Ancient Agora of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]; It is unknown which god or hero the temple honoured (was dedicated to) [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]; The temple was built from older fragments (reused material from earlier structures) [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]; The temple was built in the age of Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]; The temple was itself stripped (spoliated) later [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]; Its stripping came after the Herulian sack of Athens, in 267 AD [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]; The temple''s fragments were reused in the post-Herulian wall (its remains were found there) [SUPPORTED: https://en.wikipedia.org/wiki/Southwest_Temple]"}]'::jsonb),
    ('af02fb9c-12a1-427a-8fd2-1df0e9f5c0a7'::uuid, 'card_description', 'The largest Roman town in ancient Helvetia, from the 1st century AD. A gold bust of Marcus Aurelius was found here — one of only three such imperial portraits in gold.', 'Aventicum, capital of Roman Switzerland, raised a town wall 5.6 km long, impracticable for defence and doubtless a display of its status. The Alemanni sacked it in the 280s.', 'teaser-card-s014:af02fb9c-12a1-427a-8fd2-1df0e9f5c0a7:card_description', 'teaser-card-s014 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '849fd70f29624977dfc8042edda71ff45c71460e5a2c552e200fab3d1df4f07a|69fe8c52d6b2e3db900eaf3738d21fbc045dc5396572e0fef6eb1571250aa14d|69fe8c52d6b2e3db900eaf3738d21fbc045dc5396572e0fef6eb1571250aa14d', '[{"source": "lane WB run wb-ws-2026-09-27-01: writer teaser-wb-ws-2026-09-27-01-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aventicum, capital of Roman Switzerland, raised a town wall 5.6 km long, impracticable for defence and doubtless a display of its status. The Alemanni sacked it in the 280s."}, {"source": "lane WB run wb-ws-2026-09-27-01: checker teaser-wb-ws-2026-09-27-01-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aventicum was the capital of Roman Switzerland [S1]; its town wall was 5.6 km long [S4]; the wall was impracticable for defence [S4]; the wall was doubtless a display of the city''s status, a hedge [S4]; the Alemanni sacked the city [S5]; the sack happened in the 280s [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-01: verifier teaser-wb-ws-2026-09-27-01-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-01/OUTCOMES.jsonl", "quote": "Aventicum was a Roman town (city) of Roman Switzerland [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]; Aventicum was the capital of Roman Switzerland [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]; Aventicum had a town wall [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]; The town wall was 5.6 km long [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]; The wall was impracticable for defence [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]; The wall was doubtless a display of the city''s status [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]; The Alemanni sacked Aventicum in the 280s [SUPPORTED: https://en.wikipedia.org/wiki/Aventicum]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s014', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s014'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s014'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s014'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s014' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
